import type { ExerciseQuestion } from "../types";

export const TENSE_QUESTIONS: ExerciseQuestion[] = [
  { id: "t001", question: "She _____ to work by bus every day.", options: ["travel", "travels", "is travelling", "travelled"], correctIndex: 1, explanation: "Thì hiện tại đơn có công thức khẳng định là S + V(s/es) với chủ ngữ số ít ngôi thứ ba. Dấu hiệu 'every day' cho thấy đây là một thói quen lặp lại nên phải chia động từ theo thì này, đồng thời thêm 's' vào 'travel' vì chủ ngữ là 'she'. Đừng nhầm với 'is travelling' (thì hiện tại tiếp diễn) - dạng này chỉ dùng cho hành động đang xảy ra ngay lúc nói, không phù hợp với một thói quen hàng ngày." },
  { id: "t002", question: "Water _____ at 100°C at sea level.", options: ["boil", "boils", "is boiling", "boiled"], correctIndex: 1, explanation: "Thì hiện tại đơn (S + V-s/es) được dùng để diễn tả các sự thật khoa học, chân lý luôn đúng bất kể thời gian nào. Câu này nói về đặc tính vật lý của nước nên 'boils' là lựa chọn đúng. Không chọn 'is boiling' vì thì hiện tại tiếp diễn chỉ mô tả một hành động cụ thể đang xảy ra tạm thời, không phải một chân lý cố định." },
  { id: "t003", question: "They _____ football at the park right now.", options: ["play", "plays", "are playing", "played"], correctIndex: 2, explanation: "Cấu trúc thì hiện tại tiếp diễn là am/is/are + V-ing, dùng để tả hành động đang xảy ra ngay tại thời điểm nói. Cụm 'right now' chính là tín hiệu rõ ràng cho việc chọn 'are playing' vì chủ ngữ 'they' đi với 'are'. Tránh nhầm với 'play' (hiện tại đơn) - dạng này chỉ hợp với thói quen lặp lại, không diễn tả được việc đang diễn ra ngay lúc này." },
  { id: "t004", question: "Look! It _____ outside.", options: ["snow", "snows", "is snowing", "snowed"], correctIndex: 2, explanation: "Am/is/are + V-ing là công thức của thì hiện tại tiếp diễn, được dùng khi ta muốn gây chú ý đến điều đang xảy ra ngay trước mắt. Từ 'Look!' ở đầu câu chính là tín hiệu kinh điển báo hiệu hành động đang diễn ra, nên phải chọn 'is snowing'. Đừng chọn 'snows' (hiện tại đơn) vì dạng này chỉ hợp với hiện tượng lặp lại theo quy luật, không phải cảnh tuyết đang rơi lúc này." },
  { id: "t005", question: "She _____ to Paris for a conference next Monday. (arranged)", options: ["flies", "flew", "will fly", "is flying"], correctIndex: 3, explanation: "Thì hiện tại tiếp diễn (am/is/are + V-ing) còn có một cách dùng đặc biệt là diễn tả kế hoạch trong tương lai đã được sắp xếp/lên lịch từ trước. Từ gợi ý '(arranged)' cùng mốc thời gian 'next Monday' cho thấy chuyến bay đã được đặt sẵn, nên đáp án đúng là 'is flying'. Không chọn 'will fly' vì 'will' thường dùng cho quyết định tức thời hoặc dự đoán, không nhấn mạnh được việc đã lên kế hoạch cụ thể." },
  { id: "t006", question: "Columbus _____ America in 1492.", options: ["discovers", "has discovered", "discovered", "is discovering"], correctIndex: 2, explanation: "Thì quá khứ đơn có công thức S + V2/-ed, dùng cho hành động đã kết thúc tại một thời điểm xác định trong quá khứ. Mốc năm '1492' là dấu hiệu thời gian cụ thể đã qua, nên phải chọn 'discovered'. Tránh nhầm với 'has discovered' (hiện tại hoàn thành) - thì này không đi kèm được với một năm cụ thể trong quá khứ như thế." },
  { id: "t007", question: "I _____ my keys yesterday.", options: ["lose", "am losing", "have lost", "lost"], correctIndex: 3, explanation: "Công thức thì quá khứ đơn là S + V2/-ed (động từ bất quy tắc 'lose' chuyển thành 'lost'). Từ 'yesterday' là mốc thời gian đã qua rõ ràng, nên chỉ có thể dùng quá khứ đơn. Không chọn 'have lost' (hiện tại hoàn thành) vì thì này không được dùng chung với các trạng từ chỉ thời điểm cụ thể trong quá khứ như 'yesterday'." },
  { id: "t008", question: "We _____ dinner when the phone rang.", options: ["had", "have", "were having", "are having"], correctIndex: 2, explanation: "Thì quá khứ tiếp diễn có công thức was/were + V-ing, diễn tả một hành động đang xảy ra thì bị một hành động khác xen vào. Ở đây 'were having dinner' là hành động đang diễn ra, còn 'the phone rang' (quá khứ đơn) là hành động ngắn xen vào làm gián đoạn. Đừng chọn 'had' vì quá khứ đơn không diễn tả được tính đang-diễn-ra tại thời điểm bị gián đoạn." },
  { id: "t009", question: "She _____ a bath while her brother was watching TV.", options: ["takes", "took", "was taking", "has taken"], correctIndex: 2, explanation: "Was/were + V-ing là công thức của quá khứ tiếp diễn, dùng khi có hai hành động xảy ra song song trong quá khứ. Từ 'while' báo hiệu hai việc 'tắm' và 'xem TV' diễn ra cùng lúc nên cả hai vế đều phải chia tiếp diễn, do đó chọn 'was taking'. Không dùng 'took' (quá khứ đơn) vì hành động này không hoàn thành nhanh mà kéo dài song song với vế còn lại." },
  { id: "t010", question: "I _____ never been to Japan.", options: ["have", "had", "am", "was"], correctIndex: 0, explanation: "Have/has + V3 (past participle) là công thức của thì hiện tại hoàn thành, thường dùng để nói về kinh nghiệm đã/chưa từng trải qua tính đến hiện tại. 'Never been to' là cấu trúc quen thuộc diễn tả việc chưa từng đặt chân đến đâu đó, nên chủ ngữ 'I' phải đi với 'have'. Đừng chọn 'had' vì đó là quá khứ hoàn thành, chỉ dùng khi có một mốc thời gian quá khứ khác để so sánh, trong khi câu này không có mốc nào như vậy." },
  { id: "t011", question: "She _____ for this company since 2018.", options: ["works", "worked", "has worked", "is working"], correctIndex: 2, explanation: "Have/has + V3 là công thức hiện tại hoàn thành, và 'since + mốc thời gian' (since 2018) là dấu hiệu nhận biết kinh điển của thì này, nghĩa là hành động bắt đầu trong quá khứ và vẫn tiếp diễn đến hiện tại. Vì vậy 'she' đi với 'has worked'. Không chọn 'worked' (quá khứ đơn) vì quá khứ đơn chỉ cho biết hành động đã kết thúc, trong khi ở đây cô ấy vẫn đang làm việc tại công ty này." },
  { id: "t012", question: "Have you _____ the new restaurant on Main Street?", options: ["try", "tried", "trying", "tries"], correctIndex: 1, explanation: "Trong câu hỏi hiện tại hoàn thành, công thức là Have/Has + S + V3, nên sau 'Have you' phải là dạng phân từ hai của động từ. 'Try' là động từ có quy tắc nên V3 chỉ đơn giản là 'tried', dùng để hỏi về trải nghiệm đã từng làm hay chưa. Chú ý không chọn 'trying' hay 'tries' vì các dạng này không kết hợp được ngay sau trợ động từ 'have/has' trong cấu trúc nghi vấn." },
  { id: "t013", question: "He has just _____ from a long trip.", options: ["return", "returned", "returning", "returns"], correctIndex: 1, explanation: "Have/has + V3 kết hợp với 'just' tạo thành cấu trúc quen thuộc diễn tả một hành động vừa mới xảy ra xong. Vì chủ ngữ đã có 'has' phía trước nên chỗ trống chỉ cần điền quá khứ phân từ 'returned'. Đừng chọn 'return' hay 'returns' vì sau trợ động từ 'has' bắt buộc phải là V3, không phải động từ nguyên mẫu hay chia theo ngôi." },
  { id: "t014", question: "We have not _____ the report yet.", options: ["finish", "finished", "finishing", "finishes"], correctIndex: 1, explanation: "Câu phủ định hiện tại hoàn thành có công thức have/has + not + V3, và từ 'yet' (chưa) thường xuất hiện ở cuối câu phủ định hoặc câu hỏi để nhấn mạnh điều gì đó vẫn chưa xảy ra. Do đó ta cần điền 'finished' ngay sau 'have not'. Không chọn 'finish' vì sau 'have/has (not)' luôn phải là dạng quá khứ phân từ, không phải động từ nguyên mẫu." },
  { id: "t015", question: "By the time we arrived, the show _____.", options: ["starts", "started", "had started", "has started"], correctIndex: 2, explanation: "Had + V3 là công thức của quá khứ hoàn thành, dùng để chỉ hành động xảy ra và hoàn tất trước một hành động khác trong quá khứ. Cụm 'by the time we arrived' cho biết việc chương trình bắt đầu đã xảy ra trước khi 'chúng tôi đến', nên phải dùng 'had started'. Đừng chọn 'started' (quá khứ đơn) vì nó chỉ diễn tả một hành động đơn lẻ, không thể hiện được thứ tự trước-sau giữa hai sự việc như 'had started' làm được." },
  { id: "t016", question: "She was exhausted because she _____ all night.", options: ["work", "worked", "was working", "had been working"], correctIndex: 3, explanation: "Had been + V-ing là công thức của quá khứ hoàn thành tiếp diễn, nhấn mạnh một hành động kéo dài liên tục và gây ra kết quả ở một thời điểm khác trong quá khứ. Việc cô ấy kiệt sức (was exhausted) chính là kết quả của việc 'làm việc suốt đêm' trước đó, nên dùng 'had been working'. Không chọn 'was working' (quá khứ tiếp diễn thường) vì dạng này không nhấn mạnh được nguyên nhân - kết quả rõ ràng như quá khứ hoàn thành tiếp diễn." },
  { id: "t017", question: "'There's someone at the door.' 'I _____ get it.'", options: ["am going to", "going to", "'ll", "would"], correctIndex: 2, explanation: "'Will' (rút gọn 'll) là trợ động từ dùng cho quyết định được đưa ra ngay tại thời điểm nói, chưa hề có kế hoạch trước đó. Khi nghe thấy có người ở cửa, người nói phản xạ ngay 'I'll get it' - đây chính là quyết định tức thì điển hình. Đừng chọn 'am going to' vì cấu trúc này chỉ dùng cho những dự định đã có sẵn trong đầu trước khi nói, không phù hợp với phản xạ bất ngờ như tình huống này." },
  { id: "t018", question: "Look at those dark clouds — it _____ rain.", options: ["will", "is going to", "shall", "would"], correctIndex: 1, explanation: "'Be going to + V' được dùng khi có bằng chứng, dấu hiệu rõ ràng ngay trước mắt cho thấy điều gì sắp xảy ra. Những đám mây đen (dark clouds) chính là bằng chứng cụ thể báo hiệu trời sắp mưa, nên chọn 'is going to rain'. Không dùng 'will' vì 'will' thường dùng cho dự đoán mang tính chủ quan, không dựa trên bằng chứng cụ thể như câu này." },
  { id: "t019", question: "She _____ study abroad next year. (She's already applied)", options: ["will", "is going to", "would", "shall"], correctIndex: 1, explanation: "'Be going to + V' diễn tả một kế hoạch đã được quyết định và chuẩn bị từ trước khi nói. Chi tiết '(She's already applied)' - cô ấy đã nộp hồ sơ - chính là bằng chứng cho thấy đây là một dự định có sẵn, nên chọn 'is going to study'. Đừng chọn 'will' vì 'will' hợp với quyết định bột phát hơn là một kế hoạch đã chuẩn bị kỹ như vậy." },
  { id: "t020", question: "The train _____ at 6:15 according to the timetable.", options: ["will leave", "is going to leave", "leaves", "left"], correctIndex: 2, explanation: "Thì hiện tại đơn (S + V-s/es) được dùng đặc biệt để nói về lịch trình cố định như giờ tàu, giờ máy bay. Cụm 'according to the timetable' (theo thời khóa biểu) là dấu hiệu rõ ràng của cách dùng này, nên chọn 'leaves'. Không chọn 'will leave' vì tuy cùng nói về tương lai nhưng 'will' không nhấn mạnh được tính cố định, chính thức của một lịch trình đã niêm yết." },
  { id: "t021", question: "By next summer, she _____ her degree.", options: ["finishes", "will finish", "will have finished", "is finishing"], correctIndex: 2, explanation: "Will have + V3 là công thức của tương lai hoàn thành, dùng cho hành động dự kiến sẽ hoàn tất trước một mốc thời gian trong tương lai. 'By next summer' (trước mùa hè năm sau) chính là mốc thời gian đó, nên chọn 'will have finished'. Đừng chọn 'will finish' vì 'will' đơn thuần không nhấn mạnh được việc hoàn thành trước một thời điểm cụ thể như 'will have + V3'." },
  { id: "t022", question: "This time tomorrow, I _____ on a plane.", options: ["fly", "will fly", "will be flying", "am flying"], correctIndex: 2, explanation: "Will be + V-ing là công thức tương lai tiếp diễn, diễn tả một hành động sẽ đang xảy ra tại một thời điểm xác định trong tương lai. Cụm 'this time tomorrow' (giờ này ngày mai) chỉ rõ thời điểm đó, khi ấy người nói đang ở trên máy bay, nên chọn 'will be flying'. Không chọn 'will fly' vì dạng này chỉ nói về hành động sẽ xảy ra chung chung, không nhấn mạnh được việc đang diễn ra tại đúng thời điểm được nhắc đến." },
  { id: "t023", question: "I _____ to learn piano ever since I was a child.", options: ["want", "wanted", "have wanted", "am wanting"], correctIndex: 2, explanation: "Have/has + V3 kết hợp với 'ever since' (kể từ khi) là công thức và dấu hiệu quen thuộc của hiện tại hoàn thành, diễn tả một mong muốn bắt đầu từ quá khứ và còn kéo dài đến hiện tại. Vì vậy chọn 'have wanted'. Không chọn 'wanted' (quá khứ đơn) vì nó chỉ cho biết mong muốn đó đã xảy ra và kết thúc trong quá khứ, trong khi câu này ngụ ý ước muốn vẫn còn đến bây giờ." },
  { id: "t024", question: "He _____ for three hours when the storm finally stopped.", options: ["drove", "was driving", "had been driving", "has been driving"], correctIndex: 2, explanation: "Had been + V-ing là công thức quá khứ hoàn thành tiếp diễn, nhấn mạnh một hành động kéo dài liên tục ngay trước một mốc/sự kiện khác trong quá khứ. 'For three hours' cho thấy tính liên tục, còn 'when the storm stopped' là mốc thời gian quá khứ đó, nên chọn 'had been driving'. Đừng chọn 'has been driving' (hiện tại hoàn thành tiếp diễn) vì cả hai sự kiện trong câu đều đã xảy ra trong quá khứ, không liên quan đến hiện tại." },
  { id: "t025", question: "I _____ here since 8 AM and nobody has called me.", options: ["sit", "sat", "am sitting", "have been sitting"], correctIndex: 3, explanation: "Have/has been + V-ing là công thức của hiện tại hoàn thành tiếp diễn, dùng khi hành động bắt đầu tại một mốc trong quá khứ ('since 8 AM') và tiếp tục kéo dài đến hiện tại. Vì thế câu này cần 'have been sitting' để vừa thể hiện việc đang ngồi vừa cho thấy khoảng thời gian đã trôi qua. Đừng chọn 'am sitting' (hiện tại tiếp diễn thường) vì dạng này chỉ tả việc đang xảy ra ngay bây giờ, không gắn được với mốc thời gian bắt đầu 'since 8 AM' như 'have been sitting'." },
  { id: "t026", question: "She _____ always _____ her pen. (annoying habit)", options: ["is/losing", "has/lost", "does/lose", "was/losing"], correctIndex: 0, explanation: "Am/is/are + always + V-ing là một cách dùng đặc biệt của hiện tại tiếp diễn để than phiền về một thói quen lặp đi lặp lại gây khó chịu. Chi tiết '(annoying habit)' xác nhận đây chính là cách dùng này, nên chọn 'is/losing'. Không chọn 'does/lose' (hiện tại đơn + always) vì cách nói này chỉ đơn thuần miêu tả tần suất, thiếu sắc thái than phiền, bực bội mà 'is always losing' truyền tải được." },
  { id: "t027", question: "He told me he _____ be there on time.", options: ["will", "would", "is", "was"], correctIndex: 1, explanation: "Trong câu tường thuật (reported speech), khi câu gốc dùng 'will' thì khi lùi thì phải chuyển thành 'would'. Vì mệnh đề chính 'He told me' ở thì quá khứ, nên động từ trong mệnh đề tường thuật cũng phải lùi theo, do đó chọn 'would'. Đừng giữ nguyên 'will' vì đó là lỗi phổ biến khi quên quy tắc lùi thì trong câu tường thuật gián tiếp." },
  { id: "t028", question: "_____ you enjoy the concert last night?", options: ["Do", "Did", "Have", "Were"], correctIndex: 1, explanation: "Câu hỏi ở thì quá khứ đơn dùng trợ động từ 'Did' đứng đầu câu, theo sau là chủ ngữ và động từ nguyên mẫu. Cụm 'last night' là thời điểm cụ thể đã qua, khẳng định đây phải là câu hỏi quá khứ đơn nên chọn 'Did'. Không chọn 'Have' (hiện tại hoàn thành) vì thì này không dùng chung với mốc thời gian xác định trong quá khứ như 'last night'." },
  { id: "t029", question: "I realized I _____ my wallet at home.", options: ["leave", "left", "had left", "have left"], correctIndex: 2, explanation: "Had + V3 là công thức quá khứ hoàn thành, dùng khi một hành động xảy ra trước một hành động khác trong quá khứ. Việc 'để quên ví' đã xảy ra trước thời điểm 'nhận ra' (realized - quá khứ đơn), nên phải chọn 'had left' để thể hiện đúng trình tự trước - sau. Đừng chọn 'left' (quá khứ đơn) vì nếu dùng vậy, câu sẽ không phân biệt được việc nào xảy ra trước, việc nào xảy ra sau." },
  { id: "t030", question: "This is the most exciting film I _____ ever _____.", options: ["have/seen", "had/seen", "am/seeing", "was/seeing"], correctIndex: 0, explanation: "Have/has + V3 là công thức bắt buộc đi kèm với cấu trúc so sánh nhất 'the most... (that) I have ever + V3' để nói về trải nghiệm tính đến hiện tại. Vì đang nói ở hiện tại về một trải nghiệm chưa xác định thời điểm cụ thể, nên chọn 'have/seen'. Không chọn 'had/seen' (quá khứ hoàn thành) vì cấu trúc này chỉ dùng khi so sánh đó được đặt trong bối cảnh quá khứ, còn ở đây 'This is' cho thấy ta đang nói ở hiện tại." },
  { id: "t031", question: "She _____ three cups of coffee before the meeting started.", options: ["drinks", "drank", "had drunk", "has drunk"], correctIndex: 2, explanation: "Had + V3 (quá khứ hoàn thành) diễn tả hành động xảy ra và hoàn tất trước một hành động khác trong quá khứ. Việc uống ba tách cà phê xảy ra trước khi 'cuộc họp bắt đầu' (quá khứ đơn), nên chọn 'had drunk' để đúng trình tự thời gian. Không chọn 'drank' vì quá khứ đơn không thể hiện được việc nào xảy ra trước việc nào trong hai hành động của câu." },
  { id: "t032", question: "_____ she live near here?", options: ["Do", "Does", "Is", "Has"], correctIndex: 1, explanation: "Câu hỏi hiện tại đơn với chủ ngữ ngôi thứ ba số ít (she) dùng trợ động từ 'Does' đứng đầu câu, theo sau là động từ nguyên mẫu 'live'. Đây là câu hỏi về một sự thật/thói quen (nơi ở), nên cần trợ động từ phù hợp với ngôi của chủ ngữ. Đừng nhầm với 'Do' - trợ động từ này chỉ dùng cho chủ ngữ số nhiều hoặc I/you, không dùng với 'she'." },
  { id: "t033", question: "They _____ arrived at the airport when they realized they forgot their passports.", options: ["just", "had just", "have just", "just have"], correctIndex: 1, explanation: "Had + just + V3 là công thức quá khứ hoàn thành kết hợp với 'just', diễn tả một hành động vừa mới hoàn thành ngay trước một sự kiện khác trong quá khứ. Việc 'vừa đến sân bay' xảy ra ngay trước khi họ 'nhận ra quên hộ chiếu', nên chọn 'had just arrived'. Không chọn 'have just' (hiện tại hoàn thành) vì cả hai hành động ở đây đều nằm trong quá khứ, cần liên kết bằng quá khứ hoàn thành." },
  { id: "t034", question: "I _____ call you the moment I arrive.", options: ["am going to", "am", "'ll", "would"], correctIndex: 2, explanation: "'Will' (rút gọn 'll) + V được dùng để diễn tả lời hứa hoặc quyết định tự phát ngay tại thời điểm nói. Cụm 'the moment I arrive' (ngay khi tôi đến) đi kèm lời hứa sẽ gọi điện, một cam kết tức thời điển hình, nên chọn ''ll call'. Đừng chọn 'am going to' vì cách dùng này thiên về kế hoạch đã định sẵn hơn là một lời hứa bộc phát như câu này." },
  { id: "t035", question: "What _____ you _____ at 8pm last Saturday?", options: ["do/do", "did/do", "were/doing", "have/done"], correctIndex: 2, explanation: "Was/were + V-ing (quá khứ tiếp diễn) dùng để hỏi về một hành động đang diễn ra tại một thời điểm cụ thể trong quá khứ. Mốc '8pm last Saturday' chính là thời điểm xác định đó, nên câu hỏi cần dùng 'were you doing'. Không chọn 'did you do' (quá khứ đơn) vì cấu trúc này hỏi về một hành động đã hoàn tất, không nhấn mạnh được việc 'đang làm gì' tại một thời điểm cụ thể." },
  { id: "t036", question: "The museum _____ its 100th anniversary next year.", options: ["celebrates", "is celebrating", "will be celebrating", "celebrated"], correctIndex: 1, explanation: "Am/is/are + V-ing được dùng cho một sự kiện đã được lên lịch, sắp xếp trước cho tương lai. 'Next year' cùng với sự kiện kỷ niệm 100 năm - vốn thường được chuẩn bị từ trước - cho thấy đây là kế hoạch đã định, nên chọn 'is celebrating'. Đừng chọn 'celebrated' (quá khứ đơn) vì rõ ràng sự kiện này chưa xảy ra, nó nằm ở tương lai chứ không phải quá khứ." },
  { id: "t037", question: "After she _____ the letter, she felt much better.", options: ["sent", "has sent", "had sent", "was sending"], correctIndex: 2, explanation: "Had + V3 là công thức của quá khứ hoàn thành, thường xuất hiện sau liên từ 'after' để chỉ hành động xảy ra và hoàn tất trước hành động còn lại trong câu (felt better - quá khứ đơn). Việc 'gửi thư' hoàn tất trước khi cô ấy 'cảm thấy tốt hơn', nên chọn 'had sent'. Không chọn 'sent' (quá khứ đơn) vì dùng cả hai vế cùng quá khứ đơn sẽ làm mất đi ý nghĩa trước-sau rõ ràng mà 'after' đòi hỏi." },
  { id: "t038", question: "Don't worry — I _____ help you move this weekend.", options: ["am going to", "'ll", "would", "am"], correctIndex: 1, explanation: "'Will' (rút gọn 'll) + V diễn tả một lời đề nghị hoặc lời hứa được đưa ra ngay tại thời điểm nói, thường đi sau các câu trấn an như 'Don't worry'. Đây là phản ứng tự nhiên, chưa có kế hoạch từ trước, nên chọn ''ll help'. Đừng chọn 'am going to' vì cấu trúc đó phù hợp hơn với một dự định đã có sẵn, không phải một lời đề nghị bột phát như thế này." },
  { id: "t039", question: "She _____ in this city for twenty years before she moved abroad.", options: ["lives", "lived", "has lived", "had lived"], correctIndex: 3, explanation: "Had + V3 (quá khứ hoàn thành) diễn tả một hành động kéo dài trong quá khứ, kết thúc trước một mốc quá khứ khác. Việc sống ở thành phố này 'for twenty years' xảy ra và hoàn tất trước khi cô ấy 'moved abroad' (quá khứ đơn), nên chọn 'had lived'. Không chọn 'lived' vì nếu chỉ dùng quá khứ đơn cho cả hai vế, câu sẽ không làm rõ được thứ tự trước - sau giữa việc sống ở đó và việc chuyển đi." },
  { id: "t040", question: "I'm exhausted — I _____ since 6 AM.", options: ["work", "worked", "am working", "have been working"], correctIndex: 3, explanation: "Have/has been + V-ing là công thức hiện tại hoàn thành tiếp diễn, dùng khi muốn giải thích nguyên nhân cho một trạng thái ở hiện tại (I'm exhausted) bằng một hành động liên tục từ quá khứ đến giờ. 'Since 6 AM' là dấu hiệu thời gian bắt đầu, nên chọn 'have been working'. Không chọn 'am working' (hiện tại tiếp diễn thường) vì dạng này chỉ nói việc đang làm ngay lúc này, không thể hiện được khoảng thời gian kéo dài 'since 6 AM' như 'have been working'." },
  { id: "t041", question: "The earth _____ around the sun once every 365 days.", options: ["travels", "travel", "is travelling", "has travelled"], correctIndex: 0, explanation: "Thì hiện tại đơn (S + V-s/es) dùng để nói về chân lý khoa học không đổi theo thời gian. Việc Trái Đất quay quanh Mặt Trời là một sự thật cố định, nên chọn 'travels' (thêm -s vì chủ ngữ 'the earth' là ngôi thứ ba số ít). Đừng chọn 'is travelling' vì thì tiếp diễn chỉ hợp với hành động tạm thời, không phải một quy luật vũ trụ bất biến như thế." },
  { id: "t042", question: "She _____ never _____ sushi until she visited Japan.", options: ["had/tried", "has/tried", "was/trying", "did/try"], correctIndex: 0, explanation: "Had + never + V3 là quá khứ hoàn thành kết hợp với 'never', diễn tả một kinh nghiệm chưa từng có tính đến một thời điểm trong quá khứ. Mốc 'until she visited Japan' (quá khứ đơn) chính là điểm mốc đó, nên trước nó phải dùng quá khứ hoàn thành: 'had never tried'. Không chọn 'has/tried' (hiện tại hoàn thành) vì toàn bộ câu chuyện đang được kể ở quá khứ, không liên quan đến hiện tại." },
  { id: "t043", question: "By 10 PM tonight, I _____ this book.", options: ["finish", "will finish", "will have finished", "am finishing"], correctIndex: 2, explanation: "Will have + V3 (tương lai hoàn thành) diễn tả hành động dự kiến hoàn tất trước một mốc thời gian cụ thể trong tương lai. 'By 10 PM tonight' chính là mốc đó, nên chọn 'will have finished'. Đừng chọn 'will finish' vì dạng này chỉ nói về việc sẽ hoàn thành nói chung, không nhấn mạnh được yếu tố 'trước một thời điểm xác định' như 'will have finished'." },
  { id: "t044", question: "The kids _____ TV when their parents came home.", options: ["watch", "watched", "were watching", "have watched"], correctIndex: 2, explanation: "Was/were + V-ing là công thức quá khứ tiếp diễn, tả một hành động đang xảy ra thì có một hành động khác (came home - quá khứ đơn) xen vào. Việc bọn trẻ đang xem TV bị gián đoạn bởi việc bố mẹ về nhà, nên chọn 'were watching'. Không chọn 'watched' vì quá khứ đơn không lột tả được tính 'đang diễn ra' tại thời điểm bị gián đoạn." },
  { id: "t045", question: "I _____ German for three years but I still can't speak it well.", options: ["learn", "am learning", "have been learning", "learned"], correctIndex: 2, explanation: "Have/has been + V-ing (hiện tại hoàn thành tiếp diễn) nhấn mạnh một quá trình kéo dài liên tục từ quá khứ đến hiện tại. 'For three years' cho biết khoảng thời gian đã học, còn vế sau 'still can't speak well' cho thấy hành động này vẫn đang tiếp diễn, nên chọn 'have been learning'. Đừng chọn 'learned' (quá khứ đơn) vì dạng này ngụ ý việc học đã kết thúc, trái với ý câu là vẫn đang học." },
  { id: "t046", question: "When I _____ at the office, everyone had already left.", options: ["arrive", "arrived", "had arrived", "have arrived"], correctIndex: 1, explanation: "'When' + quá khứ đơn (S+V2/-ed) diễn tả một hành động xảy ra tại một thời điểm cụ thể, còn hành động xảy ra trước đó (everyone had already left) phải dùng quá khứ hoàn thành. Việc tôi 'đến văn phòng' là mốc thời gian tham chiếu, nên chọn 'arrived'. Không chọn 'had arrived' vì nếu cả hai vế đều là quá khứ hoàn thành, câu sẽ không còn mốc thời gian nào để so sánh trước - sau." },
  { id: "t047", question: "She _____ the piano since she was five years old.", options: ["plays", "played", "has played", "had played"], correctIndex: 2, explanation: "Have/has + V3 kết hợp với 'since' (kể từ khi) là công thức và dấu hiệu của hiện tại hoàn thành, diễn tả hành động bắt đầu trong quá khứ và tiếp tục đến hiện tại. Cô ấy bắt đầu chơi piano từ năm 5 tuổi và vẫn đang chơi, nên chọn 'has played'. Không chọn 'played' (quá khứ đơn) vì nó ngụ ý việc chơi đàn đã kết thúc, không phù hợp với ý nghĩa 'kéo dài đến hiện tại' của 'since'." },
  { id: "t048", question: "He _____ not eaten anything all day.", options: ["does", "did", "has", "is"], correctIndex: 2, explanation: "Have/has + not + V3 là công thức phủ định của hiện tại hoàn thành. Cụm 'all day' (suốt cả ngày, tính đến hiện tại) là dấu hiệu thời gian đặc trưng của thì này, và chủ ngữ 'he' cần trợ động từ 'has', nên chọn 'has'. Đừng chọn 'did' vì quá khứ đơn không dùng được với khung thời gian còn đang tiếp diễn như 'all day' (khi ngày vẫn chưa kết thúc)." },
  { id: "t049", question: "She said she _____ study harder from then on.", options: ["will", "would", "is going to", "shall"], correctIndex: 1, explanation: "Trong câu tường thuật, 'will' ở câu trực tiếp phải lùi thành 'would' khi mệnh đề chính chia ở quá khứ ('She said'). Vì vậy chọn 'would'. Không giữ nguyên 'will' vì đây là lỗi quên quy tắc lùi thì (backshift) rất thường gặp khi chuyển từ câu trực tiếp sang gián tiếp." },
  { id: "t050", question: "I _____ a strange dream last night.", options: ["have", "had", "am having", "have had"], correctIndex: 1, explanation: "Thì quá khứ đơn (S+V2/-ed) được dùng cho hành động xảy ra và kết thúc tại một thời điểm cụ thể đã qua. 'Last night' là mốc thời gian rõ ràng như vậy, nên chọn 'had' (quá khứ của 'have'). Đừng chọn 'have had' (hiện tại hoàn thành) vì thì này không thể đi kèm với trạng từ chỉ thời điểm xác định trong quá khứ như 'last night'." },
  { id: "t051", question: "The sun _____ in the west.", options: ["set", "sets", "is setting", "has set"], correctIndex: 1, explanation: "Hiện tại đơn (S+V-s/es) diễn tả chân lý/quy luật tự nhiên không đổi. Mặt Trời lặn ở hướng Tây là một sự thật cố định nên chọn 'sets' (thêm -s vì 'the sun' là ngôi thứ ba số ít). Không chọn 'is setting' vì tiếp diễn chỉ tả một sự việc tạm thời đang xảy ra, không phù hợp để nói về quy luật tự nhiên bất biến." },
  { id: "t052", question: "Dogs _____ meat.", options: ["eat", "eats", "are eating", "have eaten"], correctIndex: 0, explanation: "Hiện tại đơn diễn tả sự thật/thói quen chung mang tính khái quát. Vì 'dogs' là danh từ số nhiều nên động từ giữ nguyên dạng nguyên mẫu 'eat', không thêm -s. Đừng nhầm với 'eats' - dạng này chỉ dùng khi chủ ngữ là số ít ngôi thứ ba (he/she/it hoặc một danh từ số ít)." },
  { id: "t053", question: "My father _____ to bed at 10 PM every night.", options: ["go", "goes", "is going", "has gone"], correctIndex: 1, explanation: "Cụm 'every night' là dấu hiệu điển hình của thì hiện tại đơn, dùng cho thói quen lặp lại hàng ngày, với công thức S+V-s/es. Vì 'my father' là chủ ngữ số ít ngôi thứ ba nên động từ phải thêm -es: 'goes'. Không chọn 'is going' (tiếp diễn) vì dạng này chỉ hợp với hành động đang xảy ra ngay lúc nói, không phải một thói quen lặp lại mỗi đêm." },
  { id: "t054", question: "I _____ understand this problem. (state verb)", options: ["am not", "don't", "haven't", "wasn't"], correctIndex: 1, explanation: "'Understand' thuộc nhóm động từ trạng thái (state verb) - chỉ nhận thức, không diễn tả hành động - nên không được chia ở dạng tiếp diễn (-ing) dù ở bất kỳ ngữ cảnh nào. Câu phủ định của hiện tại đơn với chủ ngữ 'I' dùng trợ động từ 'don't', nên chọn 'don't understand'. Đừng chọn 'am not' vì thiếu động từ chính, và tuyệt đối tránh các dạng tiếp diễn với động từ trạng thái này." },
  { id: "t055", question: "She _____ like coffee — she prefers tea.", options: ["doesn't", "isn't", "hasn't", "wasn't"], correctIndex: 0, explanation: "'Like' là động từ trạng thái diễn tả sở thích, luôn chia ở thì hiện tại đơn chứ không dùng dạng tiếp diễn. Vì chủ ngữ 'she' là ngôi thứ ba số ít nên câu phủ định dùng 'doesn't' + động từ nguyên mẫu: 'doesn't like'. Không chọn 'isn't' vì thiếu động từ chính phía sau, cấu trúc phủ định đúng phải đi kèm trợ động từ 'do/does'." },
  { id: "t056", question: "He _____ know the answer right now.", options: ["isn't", "doesn't", "hasn't", "wasn't"], correctIndex: 1, explanation: "'Know' là động từ trạng thái (chỉ sự hiểu biết), không bao giờ chia ở dạng tiếp diễn kể cả khi có 'right now' đi kèm - đây là điểm dễ gây nhầm lẫn cho người học. Vì vậy phải dùng hiện tại đơn phủ định: 'doesn't know'. Đừng để 'right now' đánh lừa mà chọn 'isn't' (dạng tiếp diễn), vì động từ trạng thái luôn ưu tiên hiện tại đơn bất kể có tín hiệu thời gian tức thời hay không." },
  { id: "t057", question: "I _____ the new Taylor Swift album right now — it's great!", options: ["love", "am loving", "have loved", "loved"], correctIndex: 0, explanation: "'Love' là động từ trạng thái diễn tả cảm xúc, nên dù có 'right now' cũng không được chia ở dạng tiếp diễn - phải dùng hiện tại đơn: 'love'. Đây là lỗi rất phổ biến vì người học thấy 'right now' liền nghĩ ngay đến tiếp diễn. Đừng chọn 'am loving' vì các động từ trạng thái như 'love, like, hate, want' luôn giữ nguyên ở hiện tại đơn dù ngữ cảnh có vẻ tức thời." },
  { id: "t058", question: "She _____ her sister very much.", options: ["resembles", "is resembling", "has resembled", "resembled"], correctIndex: 0, explanation: "'Resemble' (giống) là động từ trạng thái chỉ đặc điểm cố định, luôn dùng hiện tại đơn chứ không có dạng tiếp diễn. Vì chủ ngữ 'she' là ngôi thứ ba số ít, động từ thêm -s: 'resembles'. Không chọn 'is resembling' vì các động từ trạng thái diễn tả một thực tế lâu dài (giống ai đó về ngoại hình) không bao giờ được chia ở thì tiếp diễn." },
  { id: "t059", question: "They _____ to leave tomorrow morning. (temporary arrangement)", options: ["plan", "planned", "are planning", "have planned"], correctIndex: 2, explanation: "Am/is/are + V-ing dùng cho một sắp xếp/kế hoạch cụ thể, mang tính tạm thời cho tương lai gần. Chi tiết '(temporary arrangement)' xác nhận đây chính là cách dùng đó nên chọn 'are planning'. Đừng chọn 'plan' (hiện tại đơn) vì dạng này chỉ hợp với thói quen lặp lại thường xuyên, không phải một sắp xếp riêng biệt cho 'tomorrow morning'." },
  { id: "t060", question: "He _____ always _____ his homework at the last minute. (irritating habit)", options: ["is/doing", "has/done", "does/do", "will/do"], correctIndex: 0, explanation: "Am/is/are + always + V-ing là cách dùng đặc biệt của tiếp diễn để phàn nàn về một thói quen gây khó chịu, khác với hiện tại đơn chỉ đơn thuần miêu tả tần suất. Chi tiết '(irritating habit)' khẳng định cần sắc thái than phiền này, nên chọn 'is/doing'. Không chọn 'does/do' (hiện tại đơn + always) vì cách nói đó trung tính, thiếu cảm xúc bực bội mà câu này muốn truyền tải." },
  { id: "t061", question: "I _____ a lot of coffee lately — I need to cut down.", options: ["drink", "drank", "have been drinking", "am drinking"], correctIndex: 2, explanation: "Have/has been + V-ing (hiện tại hoàn thành tiếp diễn) đi cùng 'lately' (gần đây) diễn tả một hành động lặp lại/kéo dài trong thời gian gần đây, có ảnh hưởng đến hiện tại. Việc uống nhiều cà phê gần đây khiến người nói phải 'cắt giảm', nên chọn 'have been drinking'. Đừng chọn 'drink' (hiện tại đơn) vì nó chỉ nói thói quen chung chung, không nhấn mạnh được yếu tố 'gần đây, dạo này' như 'lately' yêu cầu." },
  { id: "t062", question: "She _____ to music while she was doing her homework.", options: ["listens", "listened", "was listening", "has listened"], correctIndex: 2, explanation: "Was/were + V-ing (quá khứ tiếp diễn) dùng cho hai hành động song song trong quá khứ, thường nối bằng 'while'. Vế sau đã cho sẵn 'was doing' (tiếp diễn), nên vế trước cũng phải tương ứng: 'was listening'. Không chọn 'listened' (quá khứ đơn) vì khi có 'while' nối hai hành động cùng diễn ra song song, cả hai vế đều cần chia tiếp diễn để nhất quán." },
  { id: "t063", question: "The children _____ outside when it started to rain.", options: ["play", "played", "were playing", "have played"], correctIndex: 2, explanation: "Was/were + V-ing tả hành động đang diễn ra thì bị một hành động khác (started to rain - quá khứ đơn) xen vào làm gián đoạn. Bọn trẻ đang chơi ngoài trời thì trời đổ mưa, nên chọn 'were playing'. Đừng chọn 'played' vì quá khứ đơn không diễn tả được việc đang xảy ra tại đúng thời điểm mưa bắt đầu." },
  { id: "t064", question: "He _____ his arm when he fell off his bike.", options: ["breaks", "broke", "was breaking", "has broken"], correctIndex: 1, explanation: "Khi hai sự việc xảy ra nhanh, liên tiếp nhau trong quá khứ (không phải một việc kéo dài bị gián đoạn), cả hai đều dùng quá khứ đơn (S+V2/-ed). 'Fell' (ngã) và 'broke' (gãy) là hai hành động nối tiếp gần như tức thời, nên chọn 'broke'. Không chọn 'was breaking' (quá khứ tiếp diễn) vì việc gãy tay xảy ra ngay lập tức khi ngã, không phải một quá trình kéo dài." },
  { id: "t065", question: "I _____ that film three times already.", options: ["see", "saw", "have seen", "am seeing"], correctIndex: 2, explanation: "Have/has + V3 kết hợp với 'already' và số lần ('three times') là công thức hiện tại hoàn thành, nhấn mạnh kinh nghiệm tính đến hiện tại. Việc đã xem phim này ba lần chưa gắn với mốc thời gian cụ thể nào trong quá khứ, nên chọn 'have seen'. Đừng chọn 'saw' (quá khứ đơn) vì nó cần đi kèm một mốc thời gian xác định (ví dụ 'last year'), trong khi câu này chỉ nói về số lần trải nghiệm tính đến giờ." },
  { id: "t066", question: "Has she _____ her homework yet?", options: ["do", "did", "done", "doing"], correctIndex: 2, explanation: "Trong câu hỏi hiện tại hoàn thành, công thức là Has/Have + S + V3, và 'yet' là dấu hiệu thường thấy ở cuối câu hỏi/phủ định của thì này. Động từ 'do' ở dạng quá khứ phân từ là 'done', nên chọn 'done'. Đừng chọn 'did' hay 'doing' vì sau trợ động từ 'has' chỉ có thể là V3, không phải các dạng chia khác." },
  { id: "t067", question: "They _____ just _____ a new house.", options: ["have/bought", "had/bought", "are/buying", "were/buying"], correctIndex: 0, explanation: "Have/has + just + V3 là công thức quen thuộc diễn tả một hành động vừa mới hoàn thành xong. Chủ ngữ 'they' (số nhiều) đi với 'have', và 'buy' ở dạng quá khứ phân từ là 'bought', nên chọn 'have/bought'. Không chọn 'are/buying' (tiếp diễn) vì cách dùng đó chỉ hành động đang diễn ra, không phù hợp với ý nghĩa 'vừa mới xong' của 'just'." },
  { id: "t068", question: "How long _____ you _____ here?", options: ["do/live", "did/live", "have/lived", "are/living"], correctIndex: 2, explanation: "'How long' khi hỏi về khoảng thời gian một trạng thái đã kéo dài đến hiện tại luôn đi với thì hiện tại hoàn thành: Have/Has + S + V3. Vì vậy câu hỏi đúng là 'How long have you lived here?'. Đừng chọn 'do/live' (hiện tại đơn) vì cấu trúc này chỉ hỏi về thói quen, không hỏi được về độ dài thời gian một việc đã diễn ra tính đến bây giờ." },
  { id: "t069", question: "She _____ already _____ three chapters.", options: ["has/read", "is/reading", "was/reading", "had/read"], correctIndex: 0, explanation: "Has + already + V3 là cấu trúc hiện tại hoàn thành với 'already' (đã, rồi), diễn tả một việc đã hoàn thành tính đến hiện tại. Chủ ngữ 'she' đi với 'has', và 'read' ở dạng quá khứ phân từ vẫn là 'read' (không đổi dạng viết, chỉ đổi cách đọc), nên chọn 'has/read'. Không chọn 'is/reading' (tiếp diễn) vì 'already' không phù hợp với ý nghĩa 'đang diễn ra' của tiếp diễn." },
  { id: "t070", question: "I _____ this book for two weeks now.", options: ["read", "am reading", "have been reading", "was reading"], correctIndex: 2, explanation: "Have/has been + V-ing kết hợp với 'for + khoảng thời gian' (for two weeks) diễn tả một hành động đang kéo dài liên tục từ quá khứ đến hiện tại. Từ 'now' càng nhấn mạnh việc đọc sách vẫn đang tiếp diễn, nên chọn 'have been reading'. Đừng chọn 'read' (hiện tại đơn) vì dạng này không thể hiện được tính liên tục kéo dài qua một khoảng thời gian như 'for two weeks'." },
  { id: "t071", question: "Before she became famous, she _____ in a small village.", options: ["lives", "lived", "has lived", "had lived"], correctIndex: 3, explanation: "Had + V3 (quá khứ hoàn thành) diễn tả một hành động/trạng thái xảy ra trước một mốc quá khứ khác. Việc sống ở làng nhỏ xảy ra trước khi cô ấy 'trở nên nổi tiếng' (became - quá khứ đơn), nên chọn 'had lived'. Không chọn 'lived' vì nếu dùng quá khứ đơn cho cả hai vế, câu sẽ mất đi ý nghĩa 'trước khi' mà 'before' đang nhấn mạnh." },
  { id: "t072", question: "He _____ the keys when his wife called.", options: ["was losing", "lost", "has lost", "had been losing"], correctIndex: 0, explanation: "Was/were + V-ing tả hành động đang diễn ra thì bị gián đoạn bởi một hành động khác (called - quá khứ đơn). Vì lúc vợ anh ấy gọi thì hành động loay hoay làm mất chìa khóa đang xảy ra, nên chọn 'was losing'. Đừng chọn 'lost' (quá khứ đơn) vì hành động này cần được nhấn mạnh là đang diễn ra tại đúng lúc có cuộc gọi xen vào, không phải một sự việc đã hoàn tất gọn trong chớp mắt." },
  { id: "t073", question: "I _____ (never) _____ Thai food before I visited Bangkok.", options: ["have/eaten", "had/eaten", "was/eating", "did/eat"], correctIndex: 1, explanation: "Had + never + V3 (quá khứ hoàn thành) diễn tả kinh nghiệm chưa từng có trước một mốc thời gian trong quá khứ. Mốc đó là 'before I visited Bangkok' (quá khứ đơn), nên trước nó phải dùng quá khứ hoàn thành: 'had never eaten'. Không chọn 'have/eaten' (hiện tại hoàn thành) vì toàn câu đang kể về một trải nghiệm đã hoàn toàn thuộc về quá khứ, có mốc so sánh rõ ràng." },
  { id: "t074", question: "By the time the film started, we _____ our popcorn.", options: ["finish", "finished", "have finished", "had finished"], correctIndex: 3, explanation: "Had + V3 (quá khứ hoàn thành) diễn tả hành động hoàn tất trước một mốc khác trong quá khứ, thường đi với 'by the time'. Việc ăn hết bắp rang xảy ra trước khi phim bắt đầu, nên chọn 'had finished'. Đừng chọn 'finished' (quá khứ đơn) vì nó không làm rõ được thứ tự trước - sau mà 'by the time' đòi hỏi." },
  { id: "t075", question: "She _____ for hours when she finally found what she was looking for.", options: ["searched", "was searching", "had been searching", "has been searching"], correctIndex: 2, explanation: "Had been + V-ing (quá khứ hoàn thành tiếp diễn) nhấn mạnh một hành động kéo dài liên tục ('for hours') ngay trước khi đạt được kết quả trong quá khứ (found - quá khứ đơn). Vì vậy chọn 'had been searching'. Không chọn 'has been searching' (hiện tại hoàn thành tiếp diễn) vì toàn bộ câu chuyện, kể cả việc tìm thấy, đều đã xảy ra và kết thúc trong quá khứ." },
  { id: "t076", question: "I think it _____ be a great party tonight.", options: ["is going to", "will", "would", "shall"], correctIndex: 1, explanation: "'Will' được dùng cho dự đoán mang tính chủ quan, thường đi sau các cụm như 'I think/believe/expect'. Vì câu có 'I think' mở đầu, đây là một nhận định cá nhân về tương lai chứ không dựa trên bằng chứng cụ thể nào, nên chọn 'will'. Đừng chọn 'is going to' vì cấu trúc đó thường cần có dấu hiệu/bằng chứng rõ ràng hỗ trợ cho dự đoán, trong khi đây chỉ là ý kiến cá nhân." },
  { id: "t077", question: "Watch out! You _____ drop that vase!", options: ["will", "are going to", "would", "shall"], correctIndex: 1, explanation: "'Be going to + V' dùng khi có bằng chứng rõ ràng trước mắt cho thấy điều gì sắp xảy ra ngay lập tức. Câu cảnh báo 'Watch out!' cho thấy người nói đang thấy nguy cơ làm rơi bình hoa ngay trước mắt, nên chọn 'are going to drop'. Không chọn 'will' vì 'will' phù hợp hơn với dự đoán chung chung, thiếu tính cấp bách của một tình huống sắp xảy ra ngay tức khắc như vậy." },
  { id: "t078", question: "I promise I _____ be late again.", options: ["won't", "am not going to", "wouldn't", "don't"], correctIndex: 0, explanation: "'Will/won't' được dùng để đưa ra lời hứa cho tương lai, thường đi sau động từ 'promise'. Đây là lời hứa sẽ không đi trễ nữa, nên dạng phủ định đúng là 'won't' (= will not). Đừng chọn 'am not going to' vì tuy cũng đúng ngữ pháp trong một số ngữ cảnh, 'won't' vẫn là lựa chọn tự nhiên và phổ biến nhất khi đi kèm 'promise'." },
  { id: "t079", question: "This time next week, we _____ on a beach in Thailand.", options: ["lie", "will lie", "will be lying", "are lying"], correctIndex: 2, explanation: "Will be + V-ing (tương lai tiếp diễn) tả hành động sẽ đang diễn ra tại một thời điểm xác định trong tương lai. 'This time next week' (giờ này tuần sau) là mốc thời gian đó, khi ấy họ đang nằm trên bãi biển, nên chọn 'will be lying'. Không chọn 'will lie' vì dạng này chỉ nói việc sẽ xảy ra, không nhấn mạnh được việc đang diễn ra đúng vào thời điểm được nhắc tới." },
  { id: "t080", question: "By the end of this year, he _____ 10 books.", options: ["writes", "will write", "will have written", "is writing"], correctIndex: 2, explanation: "Will have + V3 (tương lai hoàn thành) diễn tả một việc dự kiến hoàn thành trước một mốc trong tương lai, ở đây là 'by the end of this year'. Vì vậy chọn 'will have written'. Đừng chọn 'will write' vì dạng này chỉ nói về hành động sẽ xảy ra, thiếu ý nghĩa 'hoàn tất trước một mốc cụ thể' mà 'will have + V3' thể hiện." },
  { id: "t081", question: "She _____ smoke but she gave it up last year.", options: ["used to", "is used to", "was used to", "got used to"], correctIndex: 0, explanation: "'Used to + V nguyên mẫu' diễn tả một thói quen hoặc trạng thái đã từng tồn tại trong quá khứ nhưng nay không còn nữa. Vế sau 'she gave it up last year' (đã từ bỏ) xác nhận việc hút thuốc đã chấm dứt, đúng với ý nghĩa của 'used to', nên chọn 'used to smoke'. Đừng chọn 'is used to' vì cụm này (quen với việc gì) mang nghĩa hoàn toàn khác, không liên quan đến thói quen quá khứ đã kết thúc." },
  { id: "t082", question: "He _____ walk to school when he was young.", options: ["used to", "is used to", "has used to", "was used to"], correctIndex: 0, explanation: "'Used to + V' diễn tả thói quen đã có trong quá khứ nhưng hiện tại không còn nữa, thường đi kèm cụm chỉ khoảng thời gian đã qua như 'when he was young'. Vì việc đi bộ đến trường chỉ diễn ra khi còn nhỏ, nên chọn 'used to walk'. Không chọn 'was used to' (nghĩa là 'đã quen với') vì đây là một cấu trúc khác, không diễn tả thói quen lặp lại trong quá khứ." },
  { id: "t083", question: "As a child, he _____ spend hours building model trains.", options: ["would", "will", "should", "used to"], correctIndex: 0, explanation: "'Would + V' diễn tả một thói quen, hành động lặp đi lặp lại nhiều lần trong quá khứ (không dùng được cho trạng thái). Cụm 'as a child' và hành động cụ thể 'spend hours building' phù hợp với cách dùng 'would' để hồi tưởng thói quen thời thơ ấu, nên chọn 'would'. Đừng chọn 'should' vì 'should' mang nghĩa lời khuyên/nghĩa vụ, hoàn toàn không liên quan đến việc kể lại một thói quen đã qua." },
  { id: "t084", question: "My grandfather _____ tell us stories about his youth.", options: ["would", "will", "could", "should"], correctIndex: 0, explanation: "'Would + V' dùng để hồi tưởng lại một thói quen lặp đi lặp lại trong quá khứ, thường mang sắc thái hoài niệm, phù hợp với ngữ cảnh kể chuyện về ông. Vì 'tell stories' là một hành động lặp lại nhiều lần, không phải trạng thái, nên chọn 'would tell'. Không chọn 'could' vì 'could' chỉ khả năng làm được việc gì, không diễn tả được thói quen lặp lại như 'would'." },
  { id: "t085", question: "There _____ be a cinema here, but it was demolished.", options: ["used to", "would", "will", "is going to"], correctIndex: 0, explanation: "'Used to + V' được dùng cho trạng thái/sự tồn tại trong quá khứ đã không còn nữa - ở đây là sự tồn tại của rạp chiếu phim. Vì 'be' (tồn tại) là một trạng thái chứ không phải hành động lặp lại, nên bắt buộc phải dùng 'used to', không thể dùng 'would'. Đừng chọn 'would' vì quy tắc ngữ pháp không cho phép dùng 'would' với động từ trạng thái như 'be' trong trường hợp này." },
  { id: "t086", question: "She _____ not use a computer at all before she started this job.", options: ["used to", "could", "would", "did"], correctIndex: 0, explanation: "'Used to' diễn tả một trạng thái không tồn tại trong quá khứ khi kết hợp với 'not' ngay sau nó ('used to not use'), tương đương cách nói chuẩn hơn 'didn't use to use'. Câu này nói về việc hoàn toàn không biết dùng máy tính trước khi đi làm, nên trong bốn lựa chọn, 'used to' là đáp án phù hợp nhất để ghép với 'not' có sẵn. Đừng chọn 'could' vì 'could' chỉ diễn tả khả năng làm được việc gì, không diễn tả được một trạng thái/thói quen kéo dài trong quá khứ như 'used to' làm được." },
  { id: "t087", question: "They _____ live in London before moving to Paris.", options: ["used to", "are used to", "get used to", "would"], correctIndex: 0, explanation: "'Used to + V' diễn tả một trạng thái (nơi ở) đã từng đúng trong quá khứ nhưng hiện tại đã thay đổi. Vế sau 'before moving to Paris' xác nhận họ không còn sống ở London nữa, nên chọn 'used to live'. Đừng chọn 'would' vì 'live' ở đây mang nghĩa trạng thái (nơi cư trú), không phải hành động lặp lại nên không dùng được với 'would'." },
  { id: "t088", question: "She _____ believe in ghosts, but not anymore.", options: ["used to", "would", "was", "has"], correctIndex: 0, explanation: "'Believe' là động từ trạng thái, nên khi nói về một niềm tin đã từng có trong quá khứ nhưng nay không còn ('but not anymore'), ta phải dùng 'used to believe' chứ không dùng 'would'. Điều này khẳng định lựa chọn 'used to' là đáp án đúng. Tránh chọn 'would' vì quy tắc rõ ràng: 'would' chỉ dùng được với hành động lặp lại, không dùng được với động từ trạng thái như 'believe'." },
  { id: "t089", question: "I _____ own a motorbike before I got a car.", options: ["used to", "would", "have", "am"], correctIndex: 0, explanation: "'Own' (sở hữu) là động từ trạng thái, nên diễn tả việc từng sở hữu xe máy trong quá khứ phải dùng 'used to own', không dùng 'would own'. Vế sau 'before I got a car' xác nhận đây là trạng thái đã thay đổi, càng củng cố cho 'used to'. Đừng chọn 'would' vì quy tắc ngữ pháp không cho phép kết hợp 'would' với động từ trạng thái như 'own'." },
  { id: "t090", question: "She _____ go jogging every morning when she was in college.", options: ["would", "will", "used", "has used to"], correctIndex: 0, explanation: "'Would + V' diễn tả thói quen lặp đi lặp lại trong quá khứ, phù hợp với hành động cụ thể 'go jogging every morning' (không phải trạng thái). Bối cảnh 'when she was in college' cho thấy đây là hồi tưởng về một giai đoạn quá khứ, nên chọn 'would go'. Không chọn 'used' (thiếu 'to') hay 'has used to' (sai cấu trúc) vì đây đều là các dạng viết sai của 'used to'." },
  { id: "t091", question: "I _____ think you were right, but I've changed my mind.", options: ["used to", "would", "was", "have"], correctIndex: 0, explanation: "'Think' là động từ trạng thái (chỉ suy nghĩ, quan điểm), nên khi nói về một quan điểm đã từng có trong quá khứ nhưng nay đã thay đổi ('I've changed my mind'), phải dùng 'used to think'. Điều này loại trừ 'would' vì 'would' không kết hợp được với động từ trạng thái. Hãy nhớ quy tắc: think, believe, like, own, live (nghĩa cư trú) đều là state verb và chỉ đi với 'used to', không đi với 'would'." },
  { id: "t092", question: "Careful — you _____ fall if you lean too far!", options: ["will", "are going to", "would", "shall"], correctIndex: 0, explanation: "'Will' được dùng trong câu điều kiện loại 1 (if + hiện tại đơn, ... will + V) để cảnh báo về hậu quả có thể xảy ra nếu điều kiện xảy ra. Vế 'if you lean too far' là điều kiện, nên mệnh đề chính dùng 'will fall'. Đừng chọn 'are going to' vì trong cấu trúc câu điều kiện loại 1 chuẩn mực, 'will' mới là lựa chọn tự nhiên và phổ biến nhất cho mệnh đề kết quả." },
  { id: "t093", question: "I don't think she _____ come to the meeting.", options: ["will", "is going to", "would", "shall"], correctIndex: 0, explanation: "'Will' dùng cho dự đoán cá nhân, thường xuất hiện sau 'I don't think' để đưa ra một nhận định chủ quan về tương lai. Vì đây không dựa trên bằng chứng cụ thể mà chỉ là suy đoán, nên chọn 'will'. Không chọn 'is going to' vì cấu trúc đó cần có dấu hiệu rõ ràng hỗ trợ, trong khi câu này chỉ là một phỏng đoán cá nhân." },
  { id: "t094", question: "The bus _____ at noon — don't miss it!", options: ["will leave", "is going to leave", "leaves", "left"], correctIndex: 2, explanation: "Hiện tại đơn (S+V-s/es) dùng cho lịch trình cố định như giờ xe buýt. Việc xe chạy đúng 'noon' theo lịch trình cố định, nên chọn 'leaves'. Đừng chọn 'will leave' vì tuy đúng ngữ pháp cho tương lai, nó không nhấn mạnh được tính chính thức, cố định của một lịch trình như 'leaves' làm được." },
  { id: "t095", question: "She _____ meet the director at 2 PM tomorrow. (It's in her diary)", options: ["will meet", "is meeting", "meets", "would meet"], correctIndex: 1, explanation: "Am/is/are + V-ing dùng cho một cuộc hẹn cụ thể đã được sắp xếp trước cho tương lai. Chi tiết '(It's in her diary)' - đã được ghi vào sổ lịch - là bằng chứng rõ ràng cho một kế hoạch đã định, nên chọn 'is meeting'. Không chọn 'will meet' vì 'will' không nhấn mạnh được việc cuộc hẹn đã được sắp xếp cụ thể từ trước như 'is meeting' thể hiện." },
  { id: "t096", question: "By the time you read this, I _____ for France.", options: ["leave", "am leaving", "will have left", "will leave"], correctIndex: 2, explanation: "Will have + V3 (tương lai hoàn thành) diễn tả một hành động dự kiến hoàn tất trước một mốc trong tương lai, ở đây là 'by the time you read this' (khi bạn đọc được điều này). Vì vậy chọn 'will have left'. Đừng chọn 'will leave' vì dạng này không nhấn mạnh được việc rời đi đã xảy ra xong trước thời điểm đọc thư, chỉ nói chung chung về việc sẽ rời đi." },
  { id: "t097", question: "Next month at this time, she _____ for her finals.", options: ["studies", "will study", "will be studying", "has studied"], correctIndex: 2, explanation: "Will be + V-ing (tương lai tiếp diễn) tả hành động sẽ đang diễn ra tại một thời điểm xác định trong tương lai, ở đây là 'next month at this time'. Vì vậy chọn 'will be studying'. Không chọn 'will study' vì dạng này chỉ nói việc sẽ xảy ra nói chung, thiếu tính 'đang diễn ra tại đúng thời điểm' đó." },
  { id: "t098", question: "I _____ my sister since last Christmas — I miss her.", options: ["don't see", "didn't see", "haven't seen", "won't see"], correctIndex: 2, explanation: "Have/has + not + V3 kết hợp với 'since' (kể từ khi) là công thức phủ định của hiện tại hoàn thành, diễn tả một trạng thái (không gặp) kéo dài từ quá khứ đến hiện tại. 'Since last Christmas' xác nhận điều này, nên chọn 'haven't seen'. Đừng chọn 'didn't see' (quá khứ đơn) vì thì này không dùng được với 'since', vốn luôn cần đi cùng hiện tại hoàn thành." },
  { id: "t099", question: "He _____ in three different countries before he was 30.", options: ["lived", "was living", "has lived", "had lived"], correctIndex: 3, explanation: "Had + V3 (quá khứ hoàn thành) diễn tả kinh nghiệm tích lũy trước một mốc thời gian trong quá khứ, ở đây là 'before he was 30'. Vì vậy chọn 'had lived'. Không chọn 'has lived' (hiện tại hoàn thành) vì mốc so sánh 'before he was 30' đã hoàn toàn thuộc về quá khứ, không liên quan đến hiện tại." },
  { id: "t100", question: "She was cooking when I _____ home.", options: ["come", "came", "was coming", "had come"], correctIndex: 1, explanation: "Quá khứ đơn (S+V2/-ed) diễn tả một hành động ngắn, xen vào làm gián đoạn một hành động dài hơn đang diễn ra (was cooking - quá khứ tiếp diễn). Việc tôi 'về nhà' là hành động ngắn đó, nên chọn 'came'. Đừng chọn 'was coming' (tiếp diễn) vì nếu cả hai vế đều tiếp diễn, câu sẽ không còn rõ hành động nào là nền, hành động nào là sự kiện xen vào." },
  { id: "t101", question: "My grandmother _____ five languages fluently.", options: ["speaks", "is speaking", "has spoken", "spoke"], correctIndex: 0, explanation: "Hiện tại đơn (S+V-s/es) diễn tả một khả năng/sự thật mang tính lâu dài, không đổi. Việc bà thông thạo 5 ngôn ngữ là một đặc điểm cố định, nên chọn 'speaks' (thêm -s vì 'my grandmother' là ngôi thứ ba số ít). Không chọn 'has spoken' (hiện tại hoàn thành) vì câu này không nhấn mạnh trải nghiệm hay quá trình, mà chỉ đơn thuần nêu một khả năng hiện có." },
  { id: "t102", question: "We _____ live here for long — we're moving next month.", options: ["don't", "aren't going to", "won't", "haven't"], correctIndex: 1, explanation: "'Be going to' diễn tả một kế hoạch/quyết định đã có từ trước cho tương lai. Vế sau 'we're moving next month' xác nhận đây là một quyết định đã định sẵn (sẽ không ở đây lâu), nên chọn 'aren't going to'. Đừng chọn 'won't' vì tuy cũng đúng ngữ pháp, 'be going to' phù hợp hơn khi đã có kế hoạch cụ thể (chuyển nhà tháng sau) được nhắc đến ngay trong câu." },
  { id: "t103", question: "He _____ (already) _____ his car twice this month.", options: ["had/repaired", "has/repaired", "is/repairing", "was/repairing"], correctIndex: 1, explanation: "Has + already + V3 là công thức hiện tại hoàn thành với 'already', và 'this month' (khoảng thời gian chưa kết thúc) là dấu hiệu đặc trưng của thì này. Vì vậy chọn 'has/repaired'. Không chọn 'had/repaired' (quá khứ hoàn thành) vì không có mốc quá khứ nào khác để so sánh, và 'this month' vẫn đang tiếp diễn tính đến hiện tại." },
  { id: "t104", question: "She _____ TV when I phoned her.", options: ["watches", "watched", "was watching", "has watched"], correctIndex: 2, explanation: "Was/were + V-ing tả hành động đang diễn ra thì bị gián đoạn bởi một hành động khác (phoned - quá khứ đơn). Cô ấy đang xem TV thì tôi gọi điện, nên chọn 'was watching'. Đừng chọn 'watched' vì quá khứ đơn không thể hiện được việc đang xảy ra tại đúng lúc có cuộc gọi đến." },
  { id: "t105", question: "When _____ you last _____ abroad?", options: ["do/go", "did/go", "have/gone", "were/going"], correctIndex: 1, explanation: "Câu hỏi quá khứ đơn dùng trợ động từ 'did' đứng đầu, theo sau là chủ ngữ và động từ nguyên mẫu. 'When... last' (lần cuối khi nào) hỏi về một thời điểm cụ thể đã qua, nên chọn 'did/go'. Không chọn 'have/gone' (hiện tại hoàn thành) vì cấu trúc 'When...last' luôn đòi hỏi một mốc thời gian xác định, đặc trưng của quá khứ đơn." },
  { id: "t106", question: "They _____ for 6 hours before they finally stopped to rest.", options: ["drove", "were driving", "had been driving", "have been driving"], correctIndex: 2, explanation: "Had been + V-ing (quá khứ hoàn thành tiếp diễn) nhấn mạnh một hành động kéo dài liên tục ('for 6 hours') ngay trước một sự kiện khác trong quá khứ (stopped - quá khứ đơn). Vì vậy chọn 'had been driving'. Không chọn 'have been driving' (hiện tại hoàn thành tiếp diễn) vì toàn bộ sự việc, kể cả lúc dừng lại nghỉ, đều đã xảy ra và kết thúc trong quá khứ." },
  { id: "t107", question: "I _____ believe what just happened!", options: ["can't", "couldn't", "don't", "won't"], correctIndex: 0, explanation: "'Can't believe' là cách diễn đạt tự nhiên, quen thuộc để bày tỏ sự ngạc nhiên tột độ ngay tại thời điểm nói, mang tính thành ngữ hơn là quy tắc thì đơn thuần. Sự việc 'vừa xảy ra' (just happened) khiến người nói sốc đến mức không tin nổi, nên chọn 'can't'. Đừng chọn 'don't' vì 'don't believe' mang nghĩa nghi ngờ tính xác thực của thông tin, khác với sắc thái sững sờ của 'can't believe'." },
  { id: "t108", question: "The company _____ a new product line next quarter.", options: ["launches", "has launched", "is launching", "launched"], correctIndex: 2, explanation: "Am/is/are + V-ing dùng cho một kế hoạch đã được sắp xếp cụ thể trong tương lai gần. 'Next quarter' cùng ngữ cảnh kế hoạch kinh doanh cho thấy đây là dự định đã lên lịch, nên chọn 'is launching'. Không chọn 'launches' (hiện tại đơn) vì dạng này chỉ hợp với lịch trình cố định kiểu thời khóa biểu, không phải một kế hoạch kinh doanh linh hoạt như ra mắt sản phẩm." },
  { id: "t109", question: "I _____ you that was a bad idea!", options: ["tell", "told", "was telling", "have told"], correctIndex: 1, explanation: "Quá khứ đơn (S+V2/-ed) diễn tả một hành động đã xảy ra và kết thúc trong quá khứ. Cụm 'I told you so!' là cách nói quen thuộc khi nhắc lại một lời cảnh báo đã đưa ra trước đó, nên chọn 'told'. Đừng chọn 'have told' (hiện tại hoàn thành) vì câu này đang nhắc lại một sự việc cụ thể đã xảy ra, phù hợp với sắc thái quá khứ đơn hơn." },
  { id: "t110", question: "She _____ for the job interview all week.", options: ["prepares", "has been preparing", "prepared", "is preparing"], correctIndex: 1, explanation: "Have/has been + V-ing (hiện tại hoàn thành tiếp diễn) kết hợp với 'all week' diễn tả một hành động liên tục kéo dài trong khoảng thời gian dẫn đến hiện tại. Vì vậy chọn 'has been preparing'. Không chọn 'prepared' (quá khứ đơn) vì 'all week' (cả tuần này, tính đến giờ) là khung thời gian chưa kết thúc, không phù hợp với quá khứ đơn vốn chỉ dùng cho thời gian đã khép lại." },
  { id: "t111", question: "The accident _____ while workers were repairing the bridge.", options: ["happens", "happened", "was happening", "has happened"], correctIndex: 1, explanation: "Quá khứ đơn (S+V2/-ed) diễn tả một sự kiện ngắn xảy ra trong khi một hành động khác đang diễn ra (were repairing - quá khứ tiếp diễn), thường nối bằng 'while'. Tai nạn xảy ra đột ngột giữa lúc công nhân đang sửa cầu, nên chọn 'happened'. Đừng chọn 'was happening' (tiếp diễn) vì tai nạn là một sự kiện xảy ra nhanh, không phải một quá trình kéo dài song song." },
  { id: "t112", question: "I _____ this song since I was a teenager.", options: ["love", "loved", "have loved", "am loving"], correctIndex: 2, explanation: "Have/has + V3 kết hợp với 'since' diễn tả một trạng thái/cảm xúc bắt đầu trong quá khứ và kéo dài đến hiện tại. Dù 'love' là động từ trạng thái, nó vẫn dùng được ở thì hiện tại hoàn thành khi có 'since' đi kèm, nên chọn 'have loved'. Không chọn 'am loving' vì động từ trạng thái như 'love' không chia ở dạng tiếp diễn." },
  { id: "t113", question: "He _____ chess — he finds it too complicated.", options: ["doesn't like", "isn't liking", "hasn't liked", "didn't like"], correctIndex: 0, explanation: "'Like' là động từ trạng thái, luôn chia ở hiện tại đơn. Vì chủ ngữ 'he' là ngôi thứ ba số ít, câu phủ định dùng 'doesn't' + động từ nguyên mẫu: 'doesn't like'. Đừng chọn 'isn't liking' vì động từ trạng thái không có dạng tiếp diễn, dù chủ ngữ hay ngữ cảnh câu là gì." },
  { id: "t114", question: "She _____ five emails by the time the meeting ended.", options: ["writes", "wrote", "has written", "had written"], correctIndex: 3, explanation: "Had + V3 (quá khứ hoàn thành) diễn tả hành động hoàn tất trước một mốc khác trong quá khứ, thường đi với 'by the time'. Việc viết xong 5 email xảy ra trước khi 'cuộc họp kết thúc' (quá khứ đơn), nên chọn 'had written'. Không chọn 'has written' (hiện tại hoàn thành) vì toàn bộ sự việc đã hoàn toàn thuộc về quá khứ, không liên quan đến hiện tại." },
  { id: "t115", question: "I _____ my aunt next Tuesday — can you join us?", options: ["will visit", "am visiting", "visited", "visit"], correctIndex: 1, explanation: "Am/is/are + V-ing dùng cho một cuộc hẹn/kế hoạch cụ thể đã sắp xếp cho tương lai. 'Next Tuesday' cùng lời mời 'can you join us?' cho thấy đây là một kế hoạch đã định, nên chọn 'am visiting'. Đừng chọn 'will visit' vì 'will' thường dùng cho quyết định tức thời hoặc dự đoán, không nhấn mạnh được tính đã-lên-kế-hoạch như tiếp diễn." },
  { id: "t116", question: "By next January, they _____ married for 25 years.", options: ["are", "will be", "will have been", "have been"], correctIndex: 2, explanation: "Will have been (+ tính từ/phân từ) là công thức tương lai hoàn thành cho động từ 'be', diễn tả một trạng thái sẽ kéo dài đến một mốc trong tương lai ('by next January'). Việc kết hôn 25 năm là một trạng thái kéo dài, nên chọn 'will have been'. Đừng chọn 'have been' (hiện tại hoàn thành) vì mốc 'by next January' nằm ở tương lai, cần 'will' đứng trước để chỉ rõ điều đó." },
  { id: "t117", question: "She _____ seem very happy today, does she?", options: ["doesn't", "isn't", "hasn't", "won't"], correctIndex: 0, explanation: "'Seem' là động từ trạng thái, luôn chia ở hiện tại đơn dù đang nói về 'today'. Câu hỏi đuôi 'does she?' ở cuối câu xác nhận mệnh đề chính phải dùng trợ động từ 'does' tương ứng, nên chọn 'doesn't'. Đừng chọn 'isn't' vì thiếu trợ động từ 'do/does' cần thiết để phủ định một động từ thường như 'seem'." },
  { id: "t118", question: "He _____ contain milk — you should check the label if you're lactose intolerant.", options: ["might", "may", "could", "appears to"], correctIndex: 1, explanation: "'May + V' diễn tả khả năng có thể xảy ra, thường dùng trên nhãn sản phẩm để cảnh báo về thành phần có thể có. Ngữ cảnh khuyên kiểm tra nhãn nếu không dung nạp lactose cho thấy đây là một khả năng chưa chắc chắn, nên chọn 'may'. Không chọn 'appears to' vì cụm này diễn tả vẻ bề ngoài quan sát được, không phù hợp với việc cảnh báo về thành phần ẩn có thể có trong sản phẩm." },
  { id: "t119", question: "I _____ own a car when I was in my twenties.", options: ["used to", "would", "did used to", "was used to"], correctIndex: 0, explanation: "'Own' là động từ trạng thái nên khi nói về việc từng sở hữu xe hơi trong quá khứ (nay không còn), phải dùng 'used to own', không dùng 'would'. Cụm 'when I was in my twenties' xác nhận đây là hồi tưởng về một giai đoạn quá khứ. Đừng chọn 'would' vì quy tắc rõ ràng: động từ trạng thái như 'own' không kết hợp được với 'would'." },
  { id: "t120", question: "My parents _____ argue a lot, but they are much calmer now.", options: ["used to", "would", "are used to", "will"], correctIndex: 0, explanation: "'Used to + V' diễn tả một thói quen trong quá khứ nay không còn nữa. Vế sau 'but they are much calmer now' xác nhận việc cãi nhau đã chấm dứt, nên chọn 'used to argue'. Dù 'would' cũng dùng được cho thói quen lặp lại, ở đây câu nhấn mạnh sự tương phản 'trước kia - bây giờ' nên 'used to' tự nhiên và phù hợp hơn để diễn tả sự thay đổi trạng thái." },
  { id: "t121", question: "She _____ her presentation when the fire alarm went off.", options: ["gives", "gave", "was giving", "had given"], correctIndex: 2, explanation: "Was/were + V-ing tả hành động đang diễn ra thì bị gián đoạn bởi một sự kiện khác (went off - quá khứ đơn). Cô ấy đang thuyết trình thì chuông báo cháy vang lên, nên chọn 'was giving'. Đừng chọn 'gave' (quá khứ đơn) vì nó không lột tả được việc bài thuyết trình đang diễn ra dở dang khi có sự cố xảy ra." },
  { id: "t122", question: "Do you know what _____ in 1215?", options: ["happened", "has happened", "was happening", "had happened"], correctIndex: 0, explanation: "Quá khứ đơn (S+V2/-ed) dùng cho sự kiện lịch sử xảy ra tại một thời điểm cụ thể. Mốc năm '1215' là dấu hiệu thời gian xác định trong quá khứ, nên chọn 'happened'. Không chọn 'has happened' (hiện tại hoàn thành) vì thì này không đi kèm được với một năm cụ thể đã qua rất lâu như vậy." },
  { id: "t123", question: "She _____ want anything to eat — she's not hungry.", options: ["doesn't", "isn't", "won't", "hasn't"], correctIndex: 0, explanation: "'Want' là động từ trạng thái, luôn chia ở hiện tại đơn. Vì chủ ngữ 'she' là ngôi thứ ba số ít, phủ định dùng 'doesn't' + động từ nguyên mẫu: 'doesn't want'. Đừng chọn 'isn't' vì thiếu trợ động từ 'do/does' cần thiết khi phủ định một động từ thường như 'want'." },
  { id: "t124", question: "I _____ you a hand with those bags.", options: ["give", "am giving", "will give", "'ll give"], correctIndex: 3, explanation: "'Will' (rút gọn 'll) + V diễn tả một lời đề nghị giúp đỡ được đưa ra ngay tại thời điểm nói, khi thấy ai đó cần hỗ trợ. Nhìn thấy túi đồ nặng, người nói lập tức đề nghị giúp, đây là quyết định tức thời điển hình nên chọn ''ll give'. Đừng chọn 'am giving' (hiện tại tiếp diễn) vì dạng này không diễn tả được một lời đề nghị cho tương lai gần." },
  { id: "t125", question: "She was tired because she _____ all the way from the station.", options: ["runs", "ran", "has run", "had been running"], correctIndex: 3, explanation: "Had been + V-ing (quá khứ hoàn thành tiếp diễn) giải thích nguyên nhân cho một trạng thái ở quá khứ (was tired) bằng một hành động kéo dài liên tục trước đó. Việc chạy suốt quãng đường từ ga chính là nguyên nhân khiến cô ấy mệt, nên chọn 'had been running'. Không chọn 'has run' (hiện tại hoàn thành) vì mệnh đề chính 'was tired' đã chia ở quá khứ, nên vế nguyên nhân cũng phải lùi về quá khứ hoàn thành tiếp diễn để khớp thời gian." },
  { id: "t126", question: "I _____ understand why she reacted like that.", options: ["don't", "didn't", "can't", "couldn't"], correctIndex: 1, explanation: "Quá khứ đơn phủ định (S + didn't + V nguyên mẫu) diễn tả tình trạng không hiểu tại một thời điểm cụ thể trong quá khứ (khi cô ấy phản ứng như vậy). Vì bối cảnh đã hoàn toàn thuộc về quá khứ, nên chọn 'didn't understand'. Không chọn 'don't' (hiện tại đơn) vì câu đang nói về phản ứng đã xảy ra rồi, không phải một sự việc ở hiện tại." },
  { id: "t127", question: "The match _____ when I turned on the TV.", options: ["ends", "ended", "had already ended", "is ending"], correctIndex: 2, explanation: "Had + already + V3 (quá khứ hoàn thành) diễn tả một hành động đã hoàn tất trước một mốc khác trong quá khứ (turned on - quá khứ đơn). Trận đấu đã kết thúc trước khi tôi bật TV lên, nên chọn 'had already ended'. Đừng chọn 'ended' (quá khứ đơn) vì nó không thể hiện được việc trận đấu đã xong xuôi từ trước khi tôi bật TV." },
  { id: "t128", question: "How many times _____ you _____ this film?", options: ["do/see", "did/see", "have/seen", "are/seeing"], correctIndex: 2, explanation: "'How many times' khi hỏi về số lần trải nghiệm tính đến hiện tại luôn đi với thì hiện tại hoàn thành: Have/Has + S + V3. Vì vậy câu hỏi đúng là 'How many times have you seen this film?'. Không chọn 'did/see' (quá khứ đơn) vì cấu trúc này cần một mốc thời gian cụ thể, trong khi câu hỏi này chỉ quan tâm đến tổng số lần đã xem tính đến giờ." },
  { id: "t129", question: "She _____ (already) _____ when I arrived.", options: ["has/left", "had/left", "was/leaving", "is/leaving"], correctIndex: 1, explanation: "Had + already + V3 (quá khứ hoàn thành) diễn tả hành động đã hoàn tất trước một mốc khác trong quá khứ. Việc cô ấy rời đi xảy ra trước khi tôi đến (arrived - quá khứ đơn), nên chọn 'had/left'. Không chọn 'has/left' (hiện tại hoàn thành) vì mốc so sánh 'when I arrived' đã hoàn toàn thuộc về quá khứ." },
  { id: "t130", question: "I _____ hear what you're saying — can you speak up?", options: ["don't", "can't", "won't", "am not"], correctIndex: 1, explanation: "'Can't' diễn tả khả năng (không nghe rõ) tại thời điểm hiện tại, một cách diễn đạt tự nhiên khi nhờ ai đó nói to hơn. Vì đây là vấn đề về khả năng nghe chứ không phải sự thật/thói quen, nên chọn 'can't hear'. Đừng chọn 'don't' vì 'don't hear' không phải cách diễn đạt tự nhiên trong tiếng Anh khi nói về khả năng nghe được hay không tại một thời điểm cụ thể." },
  { id: "t131", question: "She _____ here for three years before she was promoted.", options: ["works", "worked", "was working", "had been working"], correctIndex: 3, explanation: "Had been + V-ing (quá khứ hoàn thành tiếp diễn) nhấn mạnh một quá trình làm việc kéo dài liên tục ('for three years') trước một sự kiện khác trong quá khứ (was promoted - quá khứ đơn). Vì vậy chọn 'had been working'. Không chọn 'worked' (quá khứ đơn) vì nó không thể hiện được tính liên tục kéo dài suốt ba năm trước khi được thăng chức." },
  { id: "t132", question: "We _____ have dinner at 7 PM every Friday. (routine)", options: ["have", "are having", "will have", "had"], correctIndex: 0, explanation: "Hiện tại đơn (S+V-s/es) diễn tả thói quen lặp lại thường xuyên. Chi tiết '(routine)' cùng cụm 'every Friday' xác nhận đây là hoạt động lặp lại đều đặn, nên chọn 'have' (không thêm -s vì chủ ngữ 'we' là số nhiều). Đừng chọn 'are having' (tiếp diễn) vì dạng này chỉ hợp với hành động đang xảy ra tạm thời, không phải một thói quen cố định hàng tuần." },
  { id: "t133", question: "She _____ live in London — I used to see her on the Tube.", options: ["used to", "is used to", "would", "was"], correctIndex: 0, explanation: "'Used to + V' diễn tả một trạng thái (nơi ở) đã từng đúng trong quá khứ. Vế sau 'I used to see her on the Tube' cũng dùng 'used to', gợi ý về một khoảng thời gian quá khứ đã qua khi cả hai đều ở London, nên chọn 'used to live'. Đừng chọn 'would' vì 'live' mang nghĩa trạng thái cư trú, không phải hành động lặp lại, nên không kết hợp được với 'would'." },
  { id: "t134", question: "He _____ buy flowers for his wife every week. (past habit)", options: ["used to", "would", "was", "could"], correctIndex: 1, explanation: "'Would + V' diễn tả thói quen lặp đi lặp lại trong quá khứ, ở đây là hành động cụ thể 'mua hoa mỗi tuần' (không phải trạng thái) nên dùng được cả 'used to' lẫn 'would'. Chi tiết '(past habit)' xác nhận đây là thói quen đã qua, và trong bốn lựa chọn, 'would' phù hợp để diễn tả hành động lặp lại này. Đừng chọn 'was' vì đây không phải là một trạng thái đơn thuần mà là một hành động lặp lại có chủ đích." },
  { id: "t135", question: "I _____ you tomorrow as soon as I have the results.", options: ["call", "am calling", "will call", "called"], correctIndex: 2, explanation: "'Will + V' diễn tả một lời hứa cho tương lai, thường xuất hiện trong mệnh đề chính khi đi kèm mệnh đề thời gian bắt đầu bằng 'as soon as'. Lưu ý mệnh đề 'as soon as I have the results' dùng hiện tại đơn dù mang nghĩa tương lai - đây là quy tắc của mệnh đề trạng ngữ chỉ thời gian, nên chọn 'will call' cho mệnh đề chính. Đừng chọn 'am calling' (tiếp diễn) vì dạng này thiên về một kế hoạch đã sắp xếp sẵn hơn là một lời hứa gắn liền với điều kiện thời gian như câu này." },
  { id: "t136", question: "Look — the children _____ in the garden.", options: ["play", "plays", "are playing", "played"], correctIndex: 2, explanation: "'Look' là tín hiệu kinh điển của thì hiện tại tiếp diễn (am/is/are + V-ing), dùng để chỉ hành động đang xảy ra ngay trước mắt. Bọn trẻ đang chơi trong vườn ngay lúc này, nên chọn 'are playing'. Đừng chọn 'play' (hiện tại đơn) vì dạng này chỉ hợp với thói quen, không phù hợp khi có tín hiệu 'Look' báo hiệu hành động đang diễn ra." },
  { id: "t137", question: "She _____ know that I'm waiting for her.", options: ["doesn't", "isn't", "won't", "can't"], correctIndex: 0, explanation: "'Know' là động từ trạng thái, luôn chia ở hiện tại đơn. Chủ ngữ 'she' là ngôi thứ ba số ít nên phủ định dùng 'doesn't' + động từ nguyên mẫu, chọn 'doesn't know'. Đừng chọn 'isn't' vì thiếu trợ động từ 'do/does' cần thiết để phủ định động từ thường 'know'." },
  { id: "t138", question: "I _____ this problem yet — give me more time.", options: ["don't solve", "didn't solve", "haven't solved", "am not solving"], correctIndex: 2, explanation: "Have/has + not + V3 kết hợp với 'yet' (chưa) ở cuối câu là công thức phủ định quen thuộc của hiện tại hoàn thành, diễn tả việc chưa hoàn thành tính đến hiện tại. Vì vậy chọn 'haven't solved'. Không chọn 'didn't solve' (quá khứ đơn) vì 'yet' luôn đi cùng hiện tại hoàn thành để nhấn mạnh điều gì đó vẫn còn có thể xảy ra ở hiện tại/tương lai gần." },
  { id: "t139", question: "He _____ English for five years when he moved to the UK.", options: ["learns", "learned", "has learned", "had been learning"], correctIndex: 3, explanation: "Had been + V-ing (quá khứ hoàn thành tiếp diễn) nhấn mạnh quá trình học kéo dài liên tục ('for five years') trước một sự kiện khác trong quá khứ (moved - quá khứ đơn). Vì vậy chọn 'had been learning'. Không chọn 'learned' (quá khứ đơn) vì nó không thể hiện được tính liên tục suốt 5 năm trước khi anh ấy chuyển đến Anh." },
  { id: "t140", question: "They _____ to the cinema last weekend.", options: ["go", "goes", "went", "have gone"], correctIndex: 2, explanation: "Quá khứ đơn (S+V2/-ed, 'go' → 'went') dùng cho hành động đã xảy ra và kết thúc tại một thời điểm cụ thể. 'Last weekend' là mốc thời gian rõ ràng đó, nên chọn 'went'. Đừng chọn 'have gone' (hiện tại hoàn thành) vì thì này không dùng chung với các trạng từ chỉ thời điểm xác định trong quá khứ như 'last weekend'." },
  { id: "t141", question: "She _____ believe in Santa Claus when she was little.", options: ["used to", "is used to", "gets used to", "was used to"], correctIndex: 0, explanation: "'Believe' là động từ trạng thái nên khi nói về một niềm tin đã có trong quá khứ (nay không còn, ngụ ý qua 'when she was little'), phải dùng 'used to believe'. Đừng chọn 'was used to' vì cụm này (đã quen với việc gì) mang nghĩa khác hẳn, không phải nói về một niềm tin thời thơ ấu đã mất đi." },
  { id: "t142", question: "At this time next year, I _____ at university.", options: ["study", "will study", "will be studying", "am studying"], correctIndex: 2, explanation: "Will be + V-ing (tương lai tiếp diễn) tả hành động sẽ đang diễn ra tại một thời điểm xác định trong tương lai, ở đây là 'at this time next year'. Vì vậy chọn 'will be studying'. Không chọn 'will study' vì dạng này chỉ nói việc sẽ xảy ra nói chung, thiếu ý nghĩa 'đang diễn ra đúng lúc đó' của tương lai tiếp diễn." },
  { id: "t143", question: "She _____ (just) _____ the news — she looks shocked.", options: ["heard/has", "has/heard", "had/heard", "is/hearing"], correctIndex: 1, explanation: "Has + just + V3 là công thức hiện tại hoàn thành với 'just', diễn tả một việc vừa mới xảy ra xong và có kết quả rõ ràng ở hiện tại (she looks shocked). Vì vậy chọn 'has/heard'. Đừng chọn 'had/heard' (quá khứ hoàn thành) vì không có mốc quá khứ nào khác để so sánh, và kết quả 'looks shocked' đang diễn ra ở hiện tại." },
  { id: "t144", question: "They _____ the car when I passed by the garage.", options: ["fix", "fixed", "were fixing", "had fixed"], correctIndex: 2, explanation: "Was/were + V-ing tả hành động đang diễn ra thì có một hành động khác (passed by - quá khứ đơn) xảy ra cùng lúc. Họ đang sửa xe khi tôi đi ngang qua ga-ra, nên chọn 'were fixing'. Đừng chọn 'fixed' (quá khứ đơn) vì nó không lột tả được việc sửa xe đang diễn ra dở dang tại thời điểm tôi đi qua." },
  { id: "t145", question: "I _____ this word in the dictionary three times but I still forget it.", options: ["look up", "have looked up", "looked up", "had looked up"], correctIndex: 1, explanation: "Have/has + V3 kết hợp với số lần ('three times') diễn tả kinh nghiệm/hành động lặp lại tính đến hiện tại, không gắn với mốc thời gian cụ thể nào. Vế sau 'but I still forget it' (vẫn ở hiện tại) càng khẳng định cần dùng hiện tại hoàn thành, nên chọn 'have looked up'. Không chọn 'looked up' (quá khứ đơn) vì câu không có mốc thời gian quá khứ cụ thể, chỉ nói về số lần đã tra từ tính đến giờ." },
  { id: "t146", question: "She _____ work until 3 AM every night during the project.", options: ["would", "will", "could", "should"], correctIndex: 0, explanation: "'Would + V' diễn tả thói quen lặp lại nhiều lần trong quá khứ, phù hợp với hành động cụ thể 'work until 3 AM every night'. Cụm 'during the project' (trong suốt dự án đó) xác nhận đây là bối cảnh quá khứ đã qua, nên chọn 'would work'. Đừng chọn 'will' vì 'will' dùng cho tương lai, không phù hợp khi kể lại một thói quen đã thuộc về quá khứ." },
  { id: "t147", question: "He _____ the presentation by the time the boss arrives.", options: ["finishes", "will finish", "will have finished", "finished"], correctIndex: 2, explanation: "Will have + V3 (tương lai hoàn thành) diễn tả hành động dự kiến hoàn tất trước một mốc trong tương lai, ở đây là 'by the time the boss arrives'. Vì vậy chọn 'will have finished'. Đừng chọn 'will finish' vì dạng này chỉ nói việc sẽ xảy ra, không nhấn mạnh được yếu tố 'xong trước khi sếp đến' như 'will have finished'." },
  { id: "t148", question: "I _____ think that was a good idea at the time.", options: ["used to", "would", "was", "did"], correctIndex: 0, explanation: "'Think' là động từ trạng thái, khi nói về một quan điểm đã từng có trong quá khứ (ngụ ý nay đã khác qua 'at the time' - vào lúc đó) phải dùng 'used to think', không dùng 'would think'. Đừng chọn 'would' vì quy tắc rõ ràng không cho phép kết hợp 'would' với các động từ trạng thái như 'think, believe, know'." },
  { id: "t149", question: "She _____ (not) _____ yet — let's wait a bit longer.", options: ["has/arrived", "is/arriving", "was/arriving", "had/arrived"], correctIndex: 0, explanation: "Has + not + V3 kết hợp với 'yet' ở cuối câu là công thức phủ định quen thuộc của hiện tại hoàn thành, diễn tả việc chưa xảy ra tính đến hiện tại. Lời đề nghị 'let's wait a bit longer' cho thấy vẫn còn hy vọng cô ấy sẽ đến, nên chọn 'has/arrived' (has not arrived yet). Không chọn 'had/arrived' (quá khứ hoàn thành) vì tình huống đang diễn ra ở hiện tại, không phải kể lại chuyện đã qua." },
  { id: "t150", question: "By the end of the week, we _____ all our savings.", options: ["spend", "spent", "will have spent", "will spend"], correctIndex: 2, explanation: "Will have + V3 (tương lai hoàn thành) diễn tả một hành động dự kiến hoàn tất trước một mốc trong tương lai, ở đây là 'by the end of the week'. Vì vậy chọn 'will have spent'. Đừng chọn 'will spend' vì dạng này thiếu ý nghĩa 'tiêu hết trước một thời điểm cụ thể' mà 'will have spent' thể hiện." },
  { id: "t151", question: "The teacher _____ always _____ everything twice. (good habit)", options: ["is/explaining", "explains/explain", "does/explain", "explained/explains"], correctIndex: 0, explanation: "Am/is/are + always + V-ing là cách dùng đặc biệt của tiếp diễn để nhấn mạnh một thói quen đặc trưng, dù ở đây mang sắc thái tích cực '(good habit)' thay vì khó chịu. Cấu trúc này vẫn áp dụng để làm nổi bật đặc điểm riêng của giáo viên, nên chọn 'is/explaining'. Không chọn 'does/explain' (hiện tại đơn + always) vì cách nói này trung tính, không tạo được điểm nhấn về đặc trưng riêng biệt như tiếp diễn." },
  { id: "t152", question: "She _____ her keys again — that's the third time this week!", options: ["loses", "lost", "is losing", "has lost"], correctIndex: 3, explanation: "Have/has + V3 (hiện tại hoàn thành) diễn tả một hành động vừa xảy ra có liên quan/kết quả đến hiện tại, thường kèm theo việc đếm số lần lặp lại như 'the third time this week'. Vì vậy chọn 'has lost'. Không chọn 'lost' (quá khứ đơn) vì câu đang nhấn mạnh tính lặp lại gây khó chịu tính đến thời điểm hiện tại (this week - tuần này vẫn chưa kết thúc)." },
  { id: "t153", question: "They _____ their homework before dinner every day.", options: ["do", "are doing", "have done", "did"], correctIndex: 0, explanation: "Hiện tại đơn (S+V-s/es) diễn tả thói quen lặp lại hàng ngày. 'Every day' là dấu hiệu nhận biết rõ ràng, và 'they' là chủ ngữ số nhiều nên động từ giữ nguyên dạng 'do'. Đừng chọn 'are doing' (tiếp diễn) vì dạng này chỉ hợp với hành động đang xảy ra ngay lúc nói, không phải thói quen lặp lại mỗi ngày." },
  { id: "t154", question: "The project _____ by the end of this month, I promise.", options: ["completes", "will complete", "will be completed", "is completing"], correctIndex: 2, explanation: "Will be + V3 là công thức bị động của tương lai đơn (câu chủ động là 'will complete'), dùng khi nhấn mạnh kết quả/đối tượng bị tác động (the project) hơn là người thực hiện. 'By the end of this month' là mốc hoàn thành dự kiến, kết hợp với lời hứa 'I promise', nên chọn 'will be completed'. Đừng chọn 'will complete' vì đó là dạng chủ động, không phù hợp khi chủ ngữ câu là 'the project' (vật bị hoàn thành, không phải người thực hiện)." },
  { id: "t155", question: "He _____ work here — he transferred to another department.", options: ["doesn't", "didn't use to", "no longer", "used to not"], correctIndex: 1, explanation: "Phủ định chuẩn của 'used to' là 'didn't use to', diễn tả một trạng thái không còn đúng ở hiện tại (anh ấy không còn làm việc ở đây nữa vì đã chuyển phòng ban). Vế sau 'he transferred to another department' xác nhận sự thay đổi này, nên chọn 'didn't use to'. Đừng chọn 'used to not' vì đây là trật tự từ sai, không phải cách viết phủ định chuẩn của 'used to' trong tiếng Anh." },
  { id: "t156", question: "I _____ know what to do — I'm completely lost!", options: ["don't", "am not", "haven't", "didn't"], correctIndex: 0, explanation: "'Know' là động từ trạng thái, luôn chia ở hiện tại đơn. Vì chủ ngữ 'I' cần trợ động từ 'do' khi phủ định, nên chọn 'don't know'. Đừng chọn 'haven't' vì thiếu động từ chính phía sau và không phù hợp về mặt cấu trúc khi phủ định một động từ thường ở hiện tại đơn." },
  { id: "t157", question: "The match _____ at 3 PM. Don't be late.", options: ["starts", "will start", "is going to start", "is starting"], correctIndex: 0, explanation: "Hiện tại đơn (S+V-s/es) dùng cho lịch trình/thời gian biểu cố định, như giờ bắt đầu trận đấu đã được ấn định trước. Vì vậy chọn 'starts'. Đừng chọn 'will start' vì tuy đúng ngữ pháp cho tương lai, nó không nhấn mạnh được tính chính thức, không thể thay đổi của một lịch trình như 'starts' thể hiện." },
  { id: "t158", question: "She _____ write to her friends every week when she lived abroad.", options: ["used to", "would", "will", "has"], correctIndex: 1, explanation: "'Would + V' diễn tả thói quen lặp lại trong quá khứ, ở đây là hành động cụ thể 'viết thư mỗi tuần' (không phải trạng thái). Mệnh đề 'when she lived abroad' xác nhận bối cảnh quá khứ này, nên chọn 'would write'. Dù 'used to' cũng đúng ngữ pháp cho hành động lặp lại, 'would' tự nhiên hơn khi đã có 'when she lived abroad' làm rõ bối cảnh thời gian." },
  { id: "t159", question: "I _____ the doctor tomorrow at 10 AM.", options: ["see", "am seeing", "will see", "have seen"], correctIndex: 1, explanation: "Am/is/are + V-ing dùng cho một cuộc hẹn cụ thể đã được sắp xếp trước cho tương lai. 'Tomorrow at 10 AM' là thời gian cụ thể của cuộc hẹn khám bệnh, nên chọn 'am seeing'. Đừng chọn 'will see' vì 'will' phù hợp hơn với quyết định tức thời, không nhấn mạnh được việc cuộc hẹn đã được đặt lịch từ trước." },
  { id: "t160", question: "He _____ already _____ two novels before he turned 25.", options: ["wrote/has", "had/written", "has/written", "was/writing"], correctIndex: 1, explanation: "Had + already + V3 (quá khứ hoàn thành) diễn tả một thành tích đã hoàn thành trước một mốc thời gian trong quá khứ, ở đây là 'before he turned 25'. Vì vậy chọn 'had/written'. Không chọn 'has/written' (hiện tại hoàn thành) vì mốc so sánh '25 tuổi' đã hoàn toàn thuộc về quá khứ, không liên quan đến hiện tại." },
  { id: "t161", question: "I _____ a headache — do you have any paracetamol?", options: ["have", "am having", "had", "have had"], correctIndex: 0, explanation: "'Have' mang nghĩa trạng thái (cảm giác/triệu chứng) nên chia ở hiện tại đơn để diễn tả tình trạng đang có ngay lúc này. Vì vậy chọn 'have a headache'. Đừng chọn 'am having' vì trong nghĩa 'bị/có triệu chứng' như đau đầu, 'have' được coi là động từ trạng thái, không dùng dạng tiếp diễn (khác với nghĩa 'have' chỉ hành động như 'having a party')." },
  { id: "t162", question: "She _____ a great time at the party — she's still smiling!", options: ["had", "has", "is having", "has had"], correctIndex: 3, explanation: "Have/has + V3 (hiện tại hoàn thành) diễn tả một trải nghiệm vừa qua có kết quả/ảnh hưởng rõ ràng đến hiện tại. Chi tiết 'she's still smiling' (vẫn đang cười) chính là bằng chứng cho kết quả đó, nên chọn 'has had'. Đừng chọn 'had' (quá khứ đơn) vì nó không liên kết được với hiện tại như 'is still smiling', trong khi hiện tại hoàn thành làm được điều này." },
  { id: "t163", question: "When I was young, my family _____ live in the countryside.", options: ["used to", "would", "did used to", "was used to"], correctIndex: 0, explanation: "'Live' mang nghĩa trạng thái cư trú, nên khi nói về nơi ở đã từng đúng trong quá khứ (ngụ ý nay đã khác), phải dùng 'used to live' chứ không dùng 'would live'. Cụm 'when I was young' xác nhận bối cảnh quá khứ này. Đừng chọn 'would' vì quy tắc rõ ràng: động từ trạng thái không kết hợp được với 'would'." },
  { id: "t164", question: "They _____ for 20 minutes now, and there's no sign of an agreement.", options: ["argue", "argued", "are arguing", "have been arguing"], correctIndex: 3, explanation: "Have/has been + V-ing (hiện tại hoàn thành tiếp diễn) kết hợp với 'for 20 minutes now' diễn tả một hành động đang kéo dài liên tục từ quá khứ đến hiện tại. Vì vậy chọn 'have been arguing'. Đừng chọn 'are arguing' (hiện tại tiếp diễn thường) vì dạng này không thể hiện được khoảng thời gian đã trôi qua ('for 20 minutes') như hiện tại hoàn thành tiếp diễn." },
  { id: "t165", question: "She _____ meet him at the airport if he tells her what time his flight lands.", options: ["will", "would", "is going to", "shall"], correctIndex: 0, explanation: "Đây là câu điều kiện loại 1: mệnh đề if dùng hiện tại đơn ('if he tells'), còn mệnh đề chính dùng 'will + V' để nói về kết quả có khả năng xảy ra ở tương lai. Vì vậy chọn 'will meet'. Đừng chọn 'is going to' vì trong cấu trúc câu điều kiện loại 1 chuẩn mực, 'will' là lựa chọn quy tắc và tự nhiên nhất cho mệnh đề kết quả." },
  { id: "t166", question: "He _____ in this town all his life.", options: ["lives", "lived", "has lived", "is living"], correctIndex: 2, explanation: "Have/has + V3 kết hợp với 'all his life' (suốt cuộc đời anh ấy, tính đến hiện tại) là dấu hiệu của hiện tại hoàn thành, diễn tả một trạng thái kéo dài từ quá khứ đến hiện tại. Vì vậy chọn 'has lived'. Không chọn 'lived' (quá khứ đơn) vì nó ngụ ý việc sống ở đó đã kết thúc, trái với ý 'suốt cuộc đời' vẫn đang tiếp diễn." },
  { id: "t167", question: "She _____ her best friend since they had a big argument.", options: ["doesn't see", "didn't see", "hasn't seen", "won't see"], correctIndex: 2, explanation: "Have/has + not + V3 kết hợp với 'since' là công thức phủ định của hiện tại hoàn thành, diễn tả một trạng thái (không gặp) kéo dài từ một sự kiện quá khứ đến hiện tại. Vì vậy chọn 'hasn't seen'. Đừng chọn 'didn't see' (quá khứ đơn) vì thì này không dùng được với 'since', vốn luôn cần đi cùng hiện tại hoàn thành để nối quá khứ với hiện tại." },
  { id: "t168", question: "I need to hurry — the flight _____ in an hour!", options: ["leaves", "is leaving", "will leave", "left"], correctIndex: 1, explanation: "Am/is/are + V-ing dùng cho một kế hoạch/lịch trình cụ thể sắp xảy ra, đặc biệt khi muốn nhấn mạnh tính cấp bách. 'In an hour' cùng câu 'I need to hurry' cho thấy sự gấp gáp của một sự kiện đã định trước, nên chọn 'is leaving'. Không chọn 'leaves' (hiện tại đơn) vì dù cũng dùng được cho lịch trình, 'is leaving' truyền tải tốt hơn cảm giác cấp bách, sắp xảy ra ngay của tình huống này." },
  { id: "t169", question: "The scientist _____ on this research for over a decade.", options: ["works", "worked", "has been working", "is working"], correctIndex: 2, explanation: "Have/has been + V-ing (hiện tại hoàn thành tiếp diễn) kết hợp với 'for over a decade' nhấn mạnh một quá trình nghiên cứu kéo dài liên tục từ quá khứ đến hiện tại. Vì vậy chọn 'has been working'. Đừng chọn 'is working' (hiện tại tiếp diễn thường) vì dạng này chỉ tả việc đang làm ngay lúc này, không thể hiện được khoảng thời gian dài đã trôi qua." },
  { id: "t170", question: "They _____ married for 30 years next June.", options: ["will be", "are", "have been", "will have been"], correctIndex: 3, explanation: "Will have been (+ tính từ/phân từ) là công thức tương lai hoàn thành cho 'be', diễn tả một trạng thái sẽ kéo dài đến một mốc cụ thể trong tương lai ('next June'). Vì vậy chọn 'will have been married'. Đừng chọn 'have been' (hiện tại hoàn thành) vì mốc 'next June' nằm ở tương lai, cần có 'will' để chỉ rõ điều đó." },
  { id: "t171", question: "I _____ believe she actually won the competition!", options: ["can't", "don't", "won't", "haven't"], correctIndex: 0, explanation: "'Can't believe' là cách diễn đạt tự nhiên cho sự ngạc nhiên mạnh mẽ ngay tại thời điểm nói, thường dùng khi nghe một tin bất ngờ. Việc cô ấy thắng cuộc thi khiến người nói sửng sốt, nên chọn 'can't'. Đừng chọn 'don't' vì 'don't believe' thiên về nghĩa nghi ngờ tính xác thực hơn là bày tỏ sự kinh ngạc như 'can't believe'." },
  { id: "t172", question: "He _____ (already) _____ when the ambulance arrived.", options: ["died/has", "has/died", "had/died", "was/dying"], correctIndex: 2, explanation: "Had + already + V3 (quá khứ hoàn thành) diễn tả một sự việc đã xảy ra xong trước một mốc khác trong quá khứ (arrived - quá khứ đơn). Vì vậy chọn 'had/died'. Không chọn 'has/died' (hiện tại hoàn thành) vì mốc so sánh 'when the ambulance arrived' đã hoàn toàn thuộc về quá khứ." },
  { id: "t173", question: "She _____ her driving test four times so far.", options: ["fails", "failed", "has failed", "had failed"], correctIndex: 2, explanation: "Have/has + V3 kết hợp với 'so far' (cho đến nay) là công thức và dấu hiệu của hiện tại hoàn thành, diễn tả một hành động lặp lại nhiều lần trong một khoảng thời gian chưa kết thúc. Vì vậy chọn 'has failed'. Không chọn 'failed' (quá khứ đơn) vì 'so far' ngụ ý việc này vẫn có thể tiếp diễn (cô ấy có thể thi lại), không phù hợp với một hành động đã khép lại hoàn toàn." },
  { id: "t174", question: "This time last year, we _____ on holiday in Spain.", options: ["are", "were", "have been", "will be"], correctIndex: 1, explanation: "Quá khứ đơn (was/were) diễn tả trạng thái tại một thời điểm cụ thể trong quá khứ. 'This time last year' (giờ này năm ngoái) là mốc thời gian xác định đó, nên chọn 'were' (vì 'we' là chủ ngữ số nhiều). Đừng chọn 'have been' (hiện tại hoàn thành) vì thì này không dùng được với mốc thời gian quá khứ cụ thể như 'this time last year'." },
  { id: "t175", question: "They _____ the project for months before they finally gave up.", options: ["work", "worked", "had been working", "were working"], correctIndex: 2, explanation: "Had been + V-ing (quá khứ hoàn thành tiếp diễn) nhấn mạnh một quá trình làm việc kéo dài liên tục ('for months') trước một sự kiện khác trong quá khứ (gave up - quá khứ đơn). Vì vậy chọn 'had been working'. Đừng chọn 'were working' (quá khứ tiếp diễn thường) vì dạng này không thể hiện rõ được mối liên hệ 'trước khi từ bỏ' như quá khứ hoàn thành tiếp diễn." },
  { id: "t176", question: "I _____ sure she's the right person for the job.", options: ["am", "was", "have been", "will be"], correctIndex: 0, explanation: "'Sure' đi với động từ 'be' diễn tả một ý kiến/trạng thái tại hiện tại, nên chia ở hiện tại đơn: 'am sure'. Đây là quan điểm hiện tại của người nói về sự phù hợp của ứng viên, nên chọn 'am'. Đừng chọn 'have been' (hiện tại hoàn thành) vì câu không nhấn mạnh khoảng thời gian đã tin tưởng, mà chỉ đơn thuần nêu ý kiến ngay lúc nói." },
  { id: "t177", question: "She _____ the violin since she was six.", options: ["plays", "played", "has been playing", "is playing"], correctIndex: 2, explanation: "Have/has been + V-ing kết hợp với 'since' (kể từ khi) nhấn mạnh một quá trình luyện tập kéo dài liên tục từ quá khứ đến hiện tại. Vì vậy chọn 'has been playing'. Đừng chọn 'is playing' (hiện tại tiếp diễn thường) vì dạng này chỉ tả việc đang chơi ngay lúc này, không gắn được với mốc bắt đầu 'since she was six' như 'has been playing' làm được." },
  { id: "t178", question: "I _____ want to disturb you, but this is urgent.", options: ["don't", "am not", "won't", "haven't"], correctIndex: 0, explanation: "'Want' là động từ trạng thái, luôn chia ở hiện tại đơn. Chủ ngữ 'I' cần trợ động từ 'do' khi phủ định, nên chọn 'don't want'. Đừng chọn 'am not' vì thiếu động từ chính phía sau, không đúng cấu trúc phủ định của động từ thường ở hiện tại đơn." },
  { id: "t179", question: "She _____ (never) _____ such a beautiful sunset before.", options: ["sees/has", "had/seen", "saw/never", "has/seen"], correctIndex: 3, explanation: "Has + never + V3 (hiện tại hoàn thành) kết hợp với 'before' diễn tả một kinh nghiệm chưa từng có tính đến hiện tại. Vì vậy chọn 'has/seen'. Đừng chọn 'had/seen' (quá khứ hoàn thành) vì không có mốc thời gian quá khứ nào khác được nhắc đến để so sánh, câu này đang nói về trải nghiệm tính đến bây giờ." },
  { id: "t180", question: "He _____ tired when he got off the plane after a 15-hour flight.", options: ["is", "was", "has been", "had been"], correctIndex: 1, explanation: "Quá khứ đơn (was/were) diễn tả một trạng thái tại một thời điểm cụ thể trong quá khứ. 'When he got off the plane' (khi anh ấy xuống máy bay - quá khứ đơn) là mốc thời gian đó, nên chọn 'was tired'. Đừng chọn 'had been' (quá khứ hoàn thành) vì trạng thái mệt mỏi xảy ra đồng thời với lúc xuống máy bay, không phải trước một mốc quá khứ khác." },
  { id: "t181", question: "By the time the police arrived, the thief _____.", options: ["escapes", "escaped", "had escaped", "was escaping"], correctIndex: 2, explanation: "Had + V3 (quá khứ hoàn thành) diễn tả hành động đã hoàn tất trước một mốc khác trong quá khứ, thường đi với 'by the time'. Tên trộm đã trốn thoát trước khi cảnh sát đến, nên chọn 'had escaped'. Đừng chọn 'escaped' (quá khứ đơn) vì nó không làm rõ được thứ tự trước - sau giữa việc trốn thoát và việc cảnh sát đến." },
  { id: "t182", question: "I _____ agree with him on that point.", options: ["don't", "am not", "won't", "haven't"], correctIndex: 0, explanation: "'Agree' là động từ trạng thái, luôn chia ở hiện tại đơn. Chủ ngữ 'I' cần trợ động từ 'do' khi phủ định, nên chọn 'don't agree'. Đừng chọn 'am not' vì thiếu động từ chính, không đúng cấu trúc phủ định của một động từ thường ở hiện tại đơn." },
  { id: "t183", question: "She _____ still _____ for the results of the exam.", options: ["is/waiting", "has/waited", "was/waiting", "will/wait"], correctIndex: 0, explanation: "Am/is/are + V-ing (hiện tại tiếp diễn) kết hợp với 'still' diễn tả một hành động đang tiếp tục xảy ra ngay tại hiện tại. Việc chờ kết quả thi vẫn đang diễn ra, nên chọn 'is/waiting'. Đừng chọn 'has/waited' (hiện tại hoàn thành) vì câu này nhấn mạnh việc đang chờ ngay lúc nói, không phải một hành động đã hoàn tất." },
  { id: "t184", question: "They _____ in this house since 1995.", options: ["live", "lived", "are living", "have been living"], correctIndex: 3, explanation: "Have/has been + V-ing kết hợp với 'since' (kể từ khi) nhấn mạnh một hành động/trạng thái liên tục kéo dài từ một mốc trong quá khứ (1995) đến hiện tại. Vì vậy chọn 'have been living'. Đừng chọn 'live' (hiện tại đơn) vì dạng này chỉ nói thói quen chung, không thể hiện được khoảng thời gian đã trải qua kể từ 1995." },
  { id: "t185", question: "He _____ (just) _____ a shower — his hair is still wet.", options: ["took/had", "had/taken", "has/taken", "is/taking"], correctIndex: 2, explanation: "Has + just + V3 (hiện tại hoàn thành) diễn tả một hành động vừa mới xảy ra xong, có kết quả rõ ràng ở hiện tại (his hair is still wet). Vì vậy chọn 'has/taken'. Đừng chọn 'took/had' (quá khứ đơn) vì nó không liên kết trực tiếp được với kết quả 'tóc vẫn còn ướt' ở hiện tại như hiện tại hoàn thành làm được." },
  { id: "t186", question: "My sister _____ always _____ my stuff without asking! (irritating)", options: ["is/borrowing", "has/borrowed", "was/borrowing", "did/borrow"], correctIndex: 0, explanation: "Am/is/are + always + V-ing là cách dùng đặc biệt để than phiền về một thói quen gây khó chịu. Chi tiết '(irritating)' xác nhận sắc thái bực bội này, nên chọn 'is/borrowing'. Không chọn 'has/borrowed' (hiện tại hoàn thành + always - cách dùng không chuẩn) vì cấu trúc than phiền về thói quen luôn dùng tiếp diễn + always, không dùng hiện tại hoàn thành." },
  { id: "t187", question: "I _____ the meeting tomorrow, I promise.", options: ["attend", "attended", "will attend", "am attending"], correctIndex: 2, explanation: "'Will + V' diễn tả một lời hứa tự phát cho tương lai, thường đi kèm từ 'promise'. Vì vậy chọn 'will attend'. Đừng chọn 'am attending' (tiếp diễn) vì dạng này thiên về một kế hoạch đã sắp xếp sẵn hơn là một lời hứa mang tính cam kết như trong câu này." },
  { id: "t188", question: "She _____ (not) _____ anything since this morning.", options: ["has/eaten", "is/eating", "was/eating", "had/eaten"], correctIndex: 0, explanation: "Has + not + V3 kết hợp với 'since this morning' là công thức phủ định của hiện tại hoàn thành, diễn tả một trạng thái (chưa ăn) kéo dài từ sáng đến hiện tại. Vì vậy chọn 'has/eaten' (has not eaten). Đừng chọn 'had/eaten' (quá khứ hoàn thành) vì 'since this morning' vẫn đang nối đến hiện tại, không phải một mốc đã khép lại trong quá khứ." },
  { id: "t189", question: "When I was a child, I _____ be afraid of dogs.", options: ["used to", "would", "was", "am"], correctIndex: 0, explanation: "'Afraid of' diễn tả một trạng thái cảm xúc/tâm lý, nên khi nói về nỗi sợ đã từng có trong quá khứ (ngụ ý nay đã hết), phải dùng 'used to be afraid of', không dùng 'would be afraid'. Cụm 'when I was a child' xác nhận bối cảnh quá khứ. Đừng chọn 'would' vì quy tắc ngữ pháp không cho phép kết hợp 'would' với trạng thái cảm xúc như 'afraid'." },
  { id: "t190", question: "By the end of today, I _____ 50 pages of this report.", options: ["write", "will write", "will have written", "am writing"], correctIndex: 2, explanation: "Will have + V3 (tương lai hoàn thành) diễn tả một mục tiêu dự kiến hoàn thành trước một mốc trong tương lai, ở đây là 'by the end of today'. Vì vậy chọn 'will have written'. Đừng chọn 'will write' vì dạng này thiếu ý nghĩa 'hoàn tất trước một thời điểm cụ thể trong ngày' mà 'will have written' thể hiện." },
  { id: "t191", question: "She _____ know whether to laugh or cry.", options: ["doesn't", "isn't", "won't", "can't"], correctIndex: 0, explanation: "'Know' là động từ trạng thái, luôn chia ở hiện tại đơn. Chủ ngữ 'she' là ngôi thứ ba số ít nên phủ định dùng 'doesn't' + động từ nguyên mẫu, chọn 'doesn't know'. Đừng chọn 'can't' vì cấu trúc phủ định chuẩn và tự nhiên nhất cho 'know' trong ngữ cảnh trung tính này là 'doesn't know', không cần dùng động từ khuyết thiếu." },
  { id: "t192", question: "They _____ just _____ their first anniversary.", options: ["celebrated/have", "have/celebrated", "had/celebrated", "are/celebrating"], correctIndex: 1, explanation: "Have + just + V3 (hiện tại hoàn thành) diễn tả một sự kiện vừa mới xảy ra xong. Chủ ngữ 'they' (số nhiều) đi với 'have', và 'celebrate' ở dạng quá khứ phân từ là 'celebrated', nên chọn 'have/celebrated'. Đừng chọn 'celebrated/have' (sai trật tự từ) vì công thức đúng phải là have + just + V3, không phải V3 đứng trước 'have'." },
  { id: "t193", question: "She _____ in the library when her phone suddenly rang.", options: ["studies", "studied", "was studying", "had studied"], correctIndex: 2, explanation: "Was/were + V-ing tả hành động đang diễn ra thì bị gián đoạn đột ngột bởi một hành động khác (rang - quá khứ đơn), càng rõ hơn với từ 'suddenly' (bất ngờ). Cô ấy đang học trong thư viện thì điện thoại reo, nên chọn 'was studying'. Đừng chọn 'studied' (quá khứ đơn) vì nó không lột tả được việc học đang diễn ra dở dang khi bị chuông điện thoại làm gián đoạn." },
  { id: "t194", question: "He _____ (never) _____ a lie in his life. (He's very honest)", options: ["has/told", "told/never", "is/telling", "had/told"], correctIndex: 0, explanation: "Has + never + V3 (hiện tại hoàn thành) kết hợp với 'in his life' (trong suốt cuộc đời, tính đến hiện tại) diễn tả một kinh nghiệm chưa từng có. Chi tiết '(He's very honest)' củng cố cho việc anh ấy chưa từng nói dối, nên chọn 'has/told'. Đừng chọn 'told/never' (sai trật tự từ và thì) vì cấu trúc đúng phải là has + never + V3, không phải quá khứ đơn kết hợp với never theo cách này." },
  { id: "t195", question: "I _____ seem to remember where I put my glasses.", options: ["don't", "can't", "won't", "am not"], correctIndex: 0, explanation: "'Seem' là động từ trạng thái, luôn chia ở hiện tại đơn. Chủ ngữ 'I' cần trợ động từ 'do' khi phủ định, nên chọn 'don't seem'. Đừng chọn 'can't' vì cấu trúc quen thuộc và tự nhiên hơn trong tiếng Anh khi phủ định 'seem to remember' là dùng 'don't', không phải động từ khuyết thiếu." },
  { id: "t196", question: "The sun _____ by the time we reach the top of the mountain.", options: ["sets", "will set", "will have set", "is setting"], correctIndex: 2, explanation: "Will have + V3 (tương lai hoàn thành) diễn tả một hành động dự kiến hoàn tất trước một mốc trong tương lai, ở đây là 'by the time we reach the top'. Vì vậy chọn 'will have set'. Đừng chọn 'will set' vì dạng này chỉ nói việc sẽ xảy ra nói chung, thiếu ý nghĩa 'đã lặn xong trước khi lên đến đỉnh núi' như 'will have set' thể hiện." },
  { id: "t197", question: "She _____ appear very confident in interviews.", options: ["doesn't", "isn't", "won't", "hasn't"], correctIndex: 0, explanation: "'Appear' được dùng như động từ trạng thái ở đây (chỉ ấn tượng chung, không phải hành động), nên chia ở hiện tại đơn. Chủ ngữ 'she' là ngôi thứ ba số ít nên phủ định dùng 'doesn't' + động từ nguyên mẫu, chọn 'doesn't appear'. Đừng chọn 'isn't' vì thiếu trợ động từ 'do/does' cần thiết để phủ định động từ thường 'appear'." },
  { id: "t198", question: "I _____ see what you mean — could you explain it differently?", options: ["don't", "can't", "am not", "won't"], correctIndex: 1, explanation: "'Can't see' (không thể hiểu) là cách diễn đạt quen thuộc để nói về khả năng hiểu vấn đề ngay tại thời điểm nói. Lời yêu cầu giải thích lại phía sau cho thấy người nói đang gặp khó khăn hiểu ngay lúc này, nên chọn 'can't'. Đừng chọn 'don't' vì 'don't see' không tự nhiên bằng 'can't see' khi diễn tả việc không hiểu được một điều gì đó." },
  { id: "t199", question: "They _____ for over an hour by the time the last guest arrives.", options: ["wait", "will wait", "will have been waiting", "have been waiting"], correctIndex: 2, explanation: "Will have been + V-ing (tương lai hoàn thành tiếp diễn) nhấn mạnh một hành động sẽ kéo dài liên tục và hoàn thành tính đến một mốc trong tương lai ('by the time the last guest arrives'). Vì vậy chọn 'will have been waiting'. Đừng chọn 'have been waiting' (hiện tại hoàn thành tiếp diễn) vì mốc so sánh 'the last guest arrives' nằm ở tương lai, cần có 'will' phía trước." },
  { id: "t200", question: "She _____ English before, so the course was easy for her.", options: ["studies", "studied", "has studied", "had studied"], correctIndex: 3, explanation: "Had + V3 (quá khứ hoàn thành) diễn tả một kinh nghiệm đã có trước một thời điểm khác trong quá khứ (was easy - quá khứ đơn). Việc đã học tiếng Anh từ trước giải thích lý do khóa học dễ dàng với cô ấy, nên chọn 'had studied'. Đừng chọn 'has studied' (hiện tại hoàn thành) vì cả câu đang được kể ở quá khứ ('was easy'), không liên quan đến hiện tại." },
];
